const encoder = new TextEncoder();

function timingSafeEqualBytes(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

/**
 * Comparação em tempo constante sobre SHA-256 das strings (evita leak de comprimento do segredo).
 * Use para API keys / SYNC_KEY / FISCAL_WORKER_KEY. Exige ambos não vazios antes de chamar.
 */
export async function timingSafeEqualSecret(a: string, b: string): Promise<boolean> {
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", encoder.encode(a)),
    crypto.subtle.digest("SHA-256", encoder.encode(b)),
  ]);
  return timingSafeEqualBytes(new Uint8Array(da), new Uint8Array(db));
}

/** Comparação em tempo constante para strings do mesmo comprimento esperado (ex.: hex fixo). */
export function timingSafeEqualStr(a: string, b: string): boolean {
  const ba = encoder.encode(a);
  const bb = encoder.encode(b);
  return timingSafeEqualBytes(ba, bb);
}

// @types/bcryptjs usa `export =` (sem default export), entao import default
// falha no type-check (TS1192). Porem, em runtime (Deno/esm.sh) o modulo CJS
// chega como `{ default: { compareSync, ... } }` — os metodos NAO ficam no topo
// do namespace. Ou seja: `import * as bcrypt` type-checa, mas
// `bcrypt.compareSync` e `undefined` quando executa.
//
// Foi esse o efeito de 680984c7 ("Runtime identico" na mensagem do commit era
// incorreto): `bcrypt.compareSync is not a function` derrubou toda autorizacao
// de gerente que passa por este helper. Falha fechada — negava sempre, nunca
// autorizou indevidamente.
//
// Import namespace (satisfaz o type-check) + acesso via `.default` (shape real
// do runtime) resolve os dois lados.
import * as bcrypt from "https://esm.sh/bcryptjs@2.4.3";

const bcryptImpl = (bcrypt as unknown as { default: typeof bcrypt }).default;

/**
 * Compara a senha em claro com o hash bcrypt do gerente.
 *
 * Isolada e exportada para que o teste de regressao exercite exatamente o
 * caminho usado em producao — o bug de 680984c7 passou porque nao havia
 * nenhum teste tocando esta linha.
 */
export function verificarSenhaGerenteBcrypt(senha: string, hash: string): boolean {
  return bcryptImpl.compareSync(senha, hash);
}

const RATE_WINDOW_MS = 15 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const TOKEN_TTL_MS = 5 * 60 * 1000;
const UNKNOWN_IP = "unknown-ip";
const UNKNOWN_DEVICE = "unknown-device";

export type GerenteRateScope = "USER" | "IP" | "DEVICE" | "GLOBAL";

type GerenteRateContext = {
  scope: GerenteRateScope;
  identifier: string;
  limit: number;
};

type GerenteRateLimitRow = {
  failed_count: number;
  first_attempt_at: string;
  lock_until: string | null;
};

type LoggerFn = (payload: Record<string, unknown>) => void;

type ValidateOptions = {
  supabase: any;
  senha: string;
  lojaId: string | null;
  /** Empresa da operação (multiempresa): escolhe a linha padrão de pdv_config DA EMPRESA (senha de gerente). */
  empresaId?: string | null;
  userId?: string | null;
  req: Request;
  logStage: string;
  log: LoggerFn;
  limits: {
    user?: number;
    ip: number;
    device: number;
    global: number;
  };
  tokenCreatedBy: string | null;
  persistAuthAttemptsByUser: boolean;
  /**
   * Finalidade tipada da autorização. Quando informada, o token é gravado em
   * `tokens_autorizacao_operacao` (tabela separada) preso a finalidade + alvo +
   * loja + gerente aprovador. Ausente = token legado, sem finalidade, gravado em
   * `tokens_desconto_gerente` (desconto de venda, limite de crédito, retomada).
   */
  finalidade?: TokenFinalidade | null;
  /**
   * Identidade da operação autorizada. Obrigatória quando `finalidade` é
   * informada. Sangria: id da movimentação. Pagamento AP:
   * `ap:<conta_id>:<idempotency_key>` — a mesma chave de idempotência que o
   * banco deriva e grava na movimentação.
   */
  alvoId?: string | null;
};

export type TokenFinalidade = "SANGRIA" | "PAGAMENTO_AP";

const FINALIDADES_VALIDAS: readonly string[] = ["SANGRIA", "PAGAMENTO_AP"];

export function isTokenFinalidade(valor: unknown): valor is TokenFinalidade {
  return typeof valor === "string" && FINALIDADES_VALIDAS.includes(valor);
}

type ValidateResult =
  | {
    ok: true;
    status: 200;
    body: {
      ok: true;
      token: string;
      expira_em: string;
      max_desconto_percentual: number;
      gerente_id: string;
    };
  }
  | {
    ok: false;
    // 400/403: recusas do contrato tipado (alvo ausente, solicitante inválido).
    status: 400 | 401 | 403 | 429 | 500 | 503;
    body: Record<string, unknown>;
  };

function normalizeIdentifier(value: string, fallback: string): string {
  const normalized = value.trim().toLowerCase();
  return normalized ? normalized.slice(0, 200) : fallback;
}

function extractClientIp(req: Request): string {
  const cfIp = req.headers.get("cf-connecting-ip");
  if (cfIp) return normalizeIdentifier(cfIp, UNKNOWN_IP);
  const forwarded = req.headers.get("x-forwarded-for");
  if (!forwarded) return UNKNOWN_IP;
  const firstIp = forwarded.split(",")[0] ?? "";
  return normalizeIdentifier(firstIp, UNKNOWN_IP);
}

function extractDeviceFingerprint(req: Request): string {
  const fromHeader = req.headers.get("x-device-fingerprint");
  return normalizeIdentifier(fromHeader ?? "", UNKNOWN_DEVICE);
}

function isBcryptHash(hash: unknown): hash is string {
  if (typeof hash !== "string") return false;
  return /^\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}$/.test(hash);
}

function generateToken(): string {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("");
}

async function getRateLimitRow(
  supabase: any,
  ctx: GerenteRateContext,
): Promise<GerenteRateLimitRow | null> {
  const { data, error } = await supabase
    .from("gerente_auth_rate_limits")
    .select("failed_count, first_attempt_at, lock_until")
    .eq("scope", ctx.scope)
    .eq("identifier", ctx.identifier)
    .maybeSingle();
  if (error) throw new Error(`RATE_LIMIT_READ_FAILED:${ctx.scope}:${error.message}`);
  return data as GerenteRateLimitRow | null;
}

function isLocked(lockUntil: string | null, nowMs: number): boolean {
  if (!lockUntil) return false;
  const lockMs = Date.parse(lockUntil);
  return Number.isFinite(lockMs) && lockMs > nowMs;
}

async function registerFailure(
  supabase: any,
  ctx: GerenteRateContext,
  row: GerenteRateLimitRow | null,
  now: Date,
) {
  const nowMs = now.getTime();
  const firstAttemptMs = row?.first_attempt_at ? Date.parse(row.first_attempt_at) : Number.NaN;
  const insideWindow = Number.isFinite(firstAttemptMs) && nowMs - firstAttemptMs <= RATE_WINDOW_MS;

  const failedCount = insideWindow ? (row?.failed_count ?? 0) + 1 : 1;
  const firstAttemptAt = insideWindow && row?.first_attempt_at
    ? row.first_attempt_at
    : now.toISOString();
  const lockUntil = failedCount >= ctx.limit ? new Date(nowMs + LOCK_MS).toISOString() : null;

  const { error } = await supabase.from("gerente_auth_rate_limits").upsert({
    scope: ctx.scope,
    identifier: ctx.identifier,
    failed_count: failedCount,
    first_attempt_at: firstAttemptAt,
    lock_until: lockUntil,
    updated_at: now.toISOString(),
  });
  if (error) throw new Error(`RATE_LIMIT_WRITE_FAILED:${ctx.scope}:${error.message}`);

  return { failedCount, lockUntil, blockedNow: !!lockUntil };
}

async function resetRateLimit(
  supabase: any,
  ctx: GerenteRateContext,
  nowIso: string,
) {
  const { error } = await supabase.from("gerente_auth_rate_limits").upsert({
    scope: ctx.scope,
    identifier: ctx.identifier,
    failed_count: 0,
    first_attempt_at: nowIso,
    lock_until: null,
    updated_at: nowIso,
  });
  if (error) throw new Error(`RATE_LIMIT_RESET_FAILED:${ctx.scope}:${error.message}`);
}

async function precheckRateLimitLocks(
  supabase: any,
  rateContexts: GerenteRateContext[],
  nowMs: number,
  logStage: string,
  log: LoggerFn,
): Promise<ValidateResult | null> {
  for (const ctx of rateContexts) {
    const row = await getRateLimitRow(supabase, ctx);
    if (!isLocked(row?.lock_until ?? null, nowMs)) continue;
    log({
      level: "warn",
      stage: logStage,
      event: "locked_precheck",
      scope: ctx.scope,
      identifier: ctx.identifier,
      lock_until: row?.lock_until ?? null,
    });
    return {
      ok: false,
      status: 429,
      body: {
        ok: false,
        error: "LOCKED_TEMPORARILY",
        scope: ctx.scope,
        lock_until: row?.lock_until ?? null,
      },
    };
  }
  return null;
}

type GerenteConfigBundle = {
  config: {
    gerente_id: string;
    gerente_senha_bcrypt: string | null;
    max_desconto_gerente_percentual: unknown;
  };
  gerenteIdRaw: string;
};

async function loadGerenteConfigBundle(
  supabase: any,
  logStage: string,
  log: LoggerFn,
  empresaId: string | null = null,
): Promise<GerenteConfigBundle | ValidateResult> {
  const COLS = "gerente_id, gerente_senha_bcrypt, max_desconto_gerente_percentual";
  // Multiempresa: senha de gerente é da EMPRESA da operação (linha padrão loja_id NULL da empresa).
  // Sem empresa (legado) ou coluna ainda inexistente ⇒ linha id=1, como antes (cliente 1).
  let res = empresaId
    ? await supabase.from("pdv_config").select(COLS).is("loja_id", null).eq("empresa_id", empresaId).maybeSingle()
    : await supabase.from("pdv_config").select(COLS).eq("id", 1).maybeSingle();
  if (empresaId && res.error && /empresa_id/.test(String(res.error.message))) {
    res = await supabase.from("pdv_config").select(COLS).eq("id", 1).maybeSingle();
  }
  const { data: config, error: configError } = res;

  if (configError) {
    log({ level: "error", stage: logStage, error: configError.message });
    return { ok: false, status: 500, body: { ok: false, error: "ERRO_DB_CONFIG" } };
  }
  const hasBcrypt = isBcryptHash(config?.gerente_senha_bcrypt);
  if (!config || !hasBcrypt) {
    log({ level: "error", stage: logStage, error: "CONFIG_NAO_ENCONTRADA" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_NAO_ENCONTRADA" } };
  }
  const gerenteIdRaw = typeof config.gerente_id === "string" ? config.gerente_id.trim() : "";
  if (!gerenteIdRaw) {
    log({ level: "error", stage: logStage, error: "CONFIG_GERENTE_ID_AUSENTE" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_ID_AUSENTE" } };
  }
  const { data: gerenteUser, error: gerenteErr } = await supabase
    .from("usuarios")
    .select("id, perfil, ativo")
    .eq("id", gerenteIdRaw)
    .maybeSingle();
  if (gerenteErr) {
    log({ level: "error", stage: logStage, error: "GERENTE_LOOKUP_ERROR", detail: gerenteErr.message });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_INVALIDA" } };
  }
  const perfilOk =
    gerenteUser?.ativo === true &&
    (gerenteUser.perfil === "GERENTE" || gerenteUser.perfil === "DONO" || gerenteUser.perfil === "ADMIN");
  if (!perfilOk) {
    log({ level: "error", stage: logStage, error: "CONFIG_GERENTE_INVALIDA" });
    return { ok: false, status: 500, body: { ok: false, error: "CONFIG_GERENTE_INVALIDA" } };
  }
  return { config, gerenteIdRaw };
}

async function respondSenhaGerenteInvalida(
  supabase: any,
  rateContexts: GerenteRateContext[],
  now: Date,
  logStage: string,
  log: LoggerFn,
  lojaId: string | null,
  clientIp: string,
  deviceFingerprint: string,
  persistAuthAttemptsByUser: boolean,
  userId: string | null | undefined,
  nowIso: string,
): Promise<ValidateResult> {
  let lockScope: GerenteRateScope | null = null;
  let lockUntil: string | null = null;

  for (const ctx of rateContexts) {
    const row = await getRateLimitRow(supabase, ctx);
    const result = await registerFailure(supabase, ctx, row, now);
    log({
      level: "warn",
      stage: logStage,
      event: "failed_attempt",
      scope: ctx.scope,
      identifier: ctx.identifier,
      failed_count: result.failedCount,
      lock_until: result.lockUntil,
    });
    if (result.blockedNow && !lockScope) {
      lockScope = ctx.scope;
      lockUntil = result.lockUntil;
    }
  }

  if (persistAuthAttemptsByUser && userId) {
    await supabase.from("gerente_auth_attempts").upsert({
      user_id: userId,
      failed_count: 1,
      lock_until: lockUntil,
      updated_at: nowIso,
    });
  }

  log({
    level: "warn",
    stage: logStage,
    error: "SENHA_INVALIDA",
    loja_id: lojaId,
    ip: clientIp,
    device: deviceFingerprint,
    rate_scope: lockScope,
  });

  if (lockScope && lockUntil) {
    return {
      ok: false,
      status: 429,
      body: {
        ok: false,
        error: "LOCKED_TEMPORARILY",
        scope: lockScope,
        lock_until: lockUntil,
      },
    };
  }
  return { ok: false, status: 401, body: { ok: false, error: "SENHA_INVALIDA" } };
}

async function persistTokenAndResetLimits(
  supabase: any,
  token: string,
  expiraEm: string,
  lojaId: string | null,
  tokenCreatedBy: string | null,
  rateContexts: GerenteRateContext[],
  nowIso: string,
  persistAuthAttemptsByUser: boolean,
  userId: string | null | undefined,
  logStage: string,
  log: LoggerFn,
  finalidade: TokenFinalidade | null,
  alvoId: string | null,
  gerenteAprovadorId: string,
  lojaOperacaoId: string | null,
): Promise<ValidateResult | null> {
  // Token TIPADO (sangria / pagamento AP): vai para a tabela separada, preso a
  // finalidade + alvo + loja + gerente aprovador.
  //
  // `gerenteAprovadorId` vem de `pdv_config.gerente_id`, já validado (ativo e com
  // perfil aprovador) — é quem de fato teve a senha conferida. NÃO usar
  // `tokenCreatedBy`: aquele é o usuário autenticado que PEDIU a autorização, ou
  // seja, o operador solicitante. Confundir os dois registrava o solicitante como
  // aprovador da própria operação.
  //
  // A loja é derivada do servidor (`lojaOperacaoId`), não do corpo da requisição.
  const insertResult = finalidade
    ? await supabase.from("tokens_autorizacao_operacao").insert({
      token,
      finalidade,
      alvo_id: alvoId,
      loja_id: lojaOperacaoId,
      gerente_id: gerenteAprovadorId,
      solicitante_id: tokenCreatedBy,
      expira_em: expiraEm,
      usado: false,
    })
    : await supabase.from("tokens_desconto_gerente").insert({
      token,
      expira_em: expiraEm,
      usado: false,
      loja_id: lojaId,
      criado_por: tokenCreatedBy,
    });
  const { error: insertError } = insertResult;
  if (insertError) {
    log({ level: "error", stage: logStage, error: insertError.message });
    return { ok: false, status: 503, body: { ok: false, error: "ERRO_PERSISTENCIA_TOKEN" } };
  }

  for (const ctx of rateContexts) {
    await resetRateLimit(supabase, ctx, nowIso);
  }
  if (persistAuthAttemptsByUser && userId) {
    await supabase.from("gerente_auth_attempts").upsert({
      user_id: userId,
      failed_count: 0,
      lock_until: null,
      updated_at: nowIso,
    });
  }
  return null;
}

export async function validateGerenteAndIssueToken(
  options: ValidateOptions,
): Promise<ValidateResult> {
  const {
    supabase,
    senha,
    lojaId,
    empresaId,
    userId,
    req,
    logStage,
    log,
    limits,
    tokenCreatedBy,
    persistAuthAttemptsByUser,
    finalidade,
    alvoId,
  } = options;

  const now = new Date();
  const nowIso = now.toISOString();
  const nowMs = now.getTime();
  const clientIp = extractClientIp(req);
  const deviceFingerprint = extractDeviceFingerprint(req);

  const rateContexts: GerenteRateContext[] = [];
  if (userId && limits.user) {
    rateContexts.push({ scope: "USER", identifier: userId, limit: limits.user });
  }
  rateContexts.push(
    { scope: "IP", identifier: clientIp, limit: limits.ip },
    { scope: "DEVICE", identifier: deviceFingerprint, limit: limits.device },
    { scope: "GLOBAL", identifier: "global", limit: limits.global },
  );

  try {
    const locked = await precheckRateLimitLocks(supabase, rateContexts, nowMs, logStage, log);
    if (locked) return locked;

    const bundleOrErr = await loadGerenteConfigBundle(supabase, logStage, log, empresaId ?? null);
    if ("ok" in bundleOrErr) return bundleOrErr;
    const { config, gerenteIdRaw } = bundleOrErr;

    let senhaValida = false;
    const bcryptHash = typeof config.gerente_senha_bcrypt === "string" ? config.gerente_senha_bcrypt : "";
    if (isBcryptHash(bcryptHash)) {
      senhaValida = verificarSenhaGerenteBcrypt(senha, bcryptHash);
    } else {
      log({
        level: "error",
        stage: logStage,
        error: "CONFIG_HASH_INSEGURO",
      });
      return { ok: false, status: 500, body: { ok: false, error: "CONFIG_HASH_INSEGURO" } };
    }
    if (!senhaValida) {
      return await respondSenhaGerenteInvalida(
        supabase,
        rateContexts,
        now,
        logStage,
        log,
        lojaId,
        clientIp,
        deviceFingerprint,
        persistAuthAttemptsByUser,
        userId,
        nowIso,
      );
    }

    const token = generateToken();
    const expiraEm = new Date(Date.now() + TOKEN_TTL_MS).toISOString();

    // Token tipado exige alvo e loja. A loja NÃO vem do corpo da requisição: é
    // lida do cadastro do solicitante, para que o cliente não escolha o tenant.
    let lojaOperacaoId: string | null = null;
    if (finalidade) {
      if (!alvoId || !alvoId.trim()) {
        log({ level: "error", stage: logStage, error: "ALVO_OBRIGATORIO" });
        return { ok: false, status: 400, body: { ok: false, error: "ALVO_OBRIGATORIO" } };
      }
      if (!userId) {
        log({ level: "error", stage: logStage, error: "SOLICITANTE_OBRIGATORIO" });
        return { ok: false, status: 401, body: { ok: false, error: "SOLICITANTE_OBRIGATORIO" } };
      }
      const { data: solicitante, error: solicitanteErr } = await supabase
        .from("usuarios")
        .select("loja_id, ativo")
        .eq("id", userId)
        .maybeSingle();
      if (solicitanteErr || !solicitante?.ativo || !solicitante?.loja_id) {
        log({ level: "error", stage: logStage, error: "SOLICITANTE_INVALIDO" });
        return { ok: false, status: 403, body: { ok: false, error: "SOLICITANTE_INVALIDO" } };
      }
      lojaOperacaoId = solicitante.loja_id as string;
    }

    const persistErr = await persistTokenAndResetLimits(
      supabase,
      token,
      expiraEm,
      lojaId,
      tokenCreatedBy,
      rateContexts,
      nowIso,
      persistAuthAttemptsByUser,
      userId,
      logStage,
      log,
      finalidade ?? null,
      alvoId?.trim() ?? null,
      gerenteIdRaw,
      lojaOperacaoId,
    );
    if (persistErr) return persistErr;

    log({
      level: "info",
      stage: logStage,
      success: true,
      loja_id: lojaId,
      ip: clientIp,
      device: deviceFingerprint,
    });

    const maxPct = Number(config.max_desconto_gerente_percentual);
    return {
      ok: true,
      status: 200,
      body: {
        ok: true,
        token,
        expira_em: expiraEm,
        max_desconto_percentual: Number.isFinite(maxPct) && maxPct > 0 ? maxPct : 20,
        gerente_id: gerenteIdRaw,
      },
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : "UNKNOWN_ERROR";
    log({ level: "error", stage: logStage, error: errorMsg });
    return { ok: false, status: 500, body: { ok: false, error: "ERRO_INTERNO" } };
  }
}

/** Logger mínimo para Edge — evita import monorepo fora do bundle Docker. */
export function logJson(svc: string, payload: Record<string, unknown>): void {
  console.log(JSON.stringify({ ts: new Date().toISOString(), svc, ...payload }))
}

/**
 * Sentry para Edge Functions (Deno) — implementação via HTTP API.
 *
 * Não usa nenhum package externo; envia eventos diretamente ao Sentry Store API.
 * Garante que erros de venda na camada Edge sejam visíveis no mesmo projeto Sentry
 * do web e do desktop, com os mesmos tags de trace_id e venda_id.
 *
 * Configuração: variável de ambiente SENTRY_DSN na Edge Function.
 * Se ausente, todas as funções são no-ops.
 */

type SentryParsedDsn = {
  storeUrl: string
  publicKey: string
}

function parseDsn(dsn: string): SentryParsedDsn | null {
  // Formato: https://<publicKey>@<host>/<projectId>
  const m = dsn.match(/^https:\/\/([a-f0-9]+)@([^/]+)\/(\d+)$/)
  if (!m) return null
  return {
    storeUrl: `https://${m[2]}/api/${m[3]}/store/`,
    publicKey: m[1],
  }
}

let _parsedDsn: SentryParsedDsn | null | undefined = undefined

function getSentryDsn(): SentryParsedDsn | null {
  if (_parsedDsn !== undefined) return _parsedDsn
  const raw = Deno.env.get("SENTRY_DSN") ?? ""
  _parsedDsn = raw ? parseDsn(raw) : null
  return _parsedDsn
}

export type SentryEdgeContext = {
  trace_id?: string
  venda_id?: string
  caixa_id?: string
  request_id?: string
  event_type?: string
  evento?: string
  rpc?: string
  [key: string]: string | number | boolean | null | undefined
}

/**
 * Captura exceção na Edge Function com contexto de venda.
 *
 * Tags propagadas para o Sentry:
 *   - trace_id (= venda_id ou outbox_event.id)
 *   - venda_id
 *   - plataforma: 'edge'
 *   - modulo: 'pdv-sale'
 *   - evento: tipo do evento de negócio (ERRO_RPC_VENDA, ERRO_SYNC_OUTBOX…)
 */
export async function captureEdgeException(
  error: unknown,
  ctx: SentryEdgeContext = {},
): Promise<void> {
  const dsn = getSentryDsn()
  if (!dsn) return

  const err = error instanceof Error ? error : new Error(String(error))
  const traceId = ctx.trace_id ?? ctx.venda_id ?? ctx.request_id ?? "unknown"

  const stringTags: Record<string, string> = { plataforma: "edge", modulo: "pdv-sale" }
  for (const [k, v] of Object.entries(ctx)) {
    if (typeof v === "string" && v) stringTags[k] = v
  }

  const event = {
    event_id: crypto.randomUUID().replace(/-/g, ""),
    timestamp: new Date().toISOString(),
    platform: "javascript",
    server_name: "supabase-edge",
    tags: stringTags,
    extra: { trace_id: traceId, ...ctx },
    exception: {
      values: [
        {
          type: err.name,
          value: err.message,
          stacktrace: err.stack
            ? {
                frames: err.stack
                  .split("\n")
                  .slice(1)
                  .filter((l) => l.trim())
                  .map((line) => ({ abs_path: line.trim() })),
              }
            : undefined,
        },
      ],
    },
  }

  try {
    await fetch(dsn.storeUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Sentry-Auth": `Sentry sentry_version=7, sentry_client=edge-custom/1.0, sentry_key=${dsn.publicKey}`,
      },
      body: JSON.stringify(event),
      signal: AbortSignal.timeout(3000),
    })
  } catch {
    // Nunca lança — observabilidade não deve quebrar o fluxo de venda
  }
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export type CaixaSyncInsert = {
  id: string;
  operador_id: string | null;
  valor_inicial: number;
  status: "ABERTO";
  loja_id: string;
};

export function requireExplicitLojaId(raw: unknown): string {
  if (typeof raw !== "string" || !UUID_RE.test(raw.trim())) {
    throw new Error("CAIXA_LOJA_OBRIGATORIA");
  }
  return raw.trim();
}

export function assertMesmaLoja(existente: string | null, informada: string): void {
  if (existente == null || existente !== informada) {
    throw new Error("CAIXA_LOJA_DIVERGENTE");
  }
}

export function caixaInsertForLoja(input: {
  id: string;
  operadorId: string | null;
  valorInicial: number;
  lojaId: unknown;
}): CaixaSyncInsert {
  return {
    id: input.id,
    operador_id: input.operadorId,
    valor_inicial: input.valorInicial,
    status: "ABERTO",
    loja_id: requireExplicitLojaId(input.lojaId),
  };
}

// ---------------------------------------------------------------------------------------------
// Compatibilidade com PDV legado (Build A: anterior a 10/10, não envia loja_id) — SÓ modo legado
// (chave compartilhada, HMAC já validado). Resolve a loja NO SERVIDOR, de forma determinística:
//   1. loja do caixa já existente no servidor (caixa aberto antes, por qualquer build);
//   2. senão, a ÚNICA loja ativa. Com 0 ou >1 lojas ativas o evento é REJEITADO (sem adivinhar).
// `pdv_config` não entra: é singleton global (não é por dispositivo) e com >1 loja seria palpite.
// Header x-loja-id, se veio, só pode confirmar a loja resolvida. Builds B/C (loja_id presente) e o
// modo dispositivo não passam por aqui.
export type LojaLegadoLookups = {
  caixaLoja: (caixaId: string) => Promise<string | null>;
  lojasAtivas: () => Promise<string[]>;
};
export type LojaLegadoAuditoria = { fonte: "caixa" | "loja_unica"; loja_id: string; caixa_id: string | null };

export async function aplicarLojaLegado<E extends { tipo: string; payload_json: string }>(
  ev: E,
  headerLojaId: string | null,
  lookups: LojaLegadoLookups,
): Promise<{ ev: E; auditoria: LojaLegadoAuditoria | null }> {
  if (ev.tipo !== "CAIXA_ABERTO" && ev.tipo !== "VENDA_REGISTRADA") return { ev, auditoria: null };
  const p = JSON.parse(ev.payload_json) as Record<string, unknown>;
  if (!p || typeof p !== "object" || Array.isArray(p)) return { ev, auditoria: null };
  if (p.loja_id !== undefined && p.loja_id !== null && p.loja_id !== "") return { ev, auditoria: null };
  const rawCaixa = ev.tipo === "CAIXA_ABERTO" ? p.id : p.caixa_id;
  const caixaId = typeof rawCaixa === "string" && UUID_RE.test(rawCaixa.trim()) ? rawCaixa.trim() : null;
  let loja = caixaId ? await lookups.caixaLoja(caixaId) : null;
  let fonte: LojaLegadoAuditoria["fonte"] = "caixa";
  if (!loja) {
    const ativas = [...new Set(await lookups.lojasAtivas())];
    if (ativas.length !== 1) throw new Error(ativas.length === 0 ? "LOJA_LEGADO_INDEFINIDA" : "LOJA_LEGADO_AMBIGUA");
    loja = ativas[0];
    fonte = "loja_unica";
  }
  const header = headerLojaId?.trim() || null;
  if (header && header !== loja) throw new Error("LOJA_LEGADO_DIVERGENTE_DO_HEADER");
  return {
    ev: { ...ev, payload_json: JSON.stringify({ ...p, loja_id: loja }) },
    auditoria: { fonte, loja_id: loja, caixa_id: caixaId },
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";

/** Payload mínimo já validado por `parseVendaPayload` / `processVenda`. */
export type VendaPayloadFiscalSync = {
  venda_id: string;
  caixa_id?: string | null;
  operador_id?: string | null;
  forma_pagamento: string;
  total_bruto: number;
  total_desconto: number;
  total_liquido: number;
  itens: Array<{
    produto_id: string;
    /** Nome capturado no cliente offline (opcional) — usado só se a busca a `produtos` não achar a linha. */
    nome?: string;
    quantidade: number;
    preco_original: number;
    preco_unitario: number;
  }>;
};

function isUuid(s: string | null | undefined): s is string {
  if (!s || typeof s !== "string") return false;
  const t = s.trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t);
}

function roundMoney2(n: number): number {
  return Math.round(n * 100) / 100;
}

function abortFiscalEnqueue(
  log: (p: Record<string, unknown>) => void,
  vendaId: string,
  detail: string,
): never {
  log({ level: "error", stage: "fiscal_enqueue_sync", venda_id: vendaId, detail, retry: true });
  throw new Error(`FISCAL_ENFILEIRAR_PENDENTE:${detail}`);
}

function resolveFiscalDocType(raw: string | undefined): "NFC_E_STUB" | "NFCE" | "NFE" {
  const t = (raw ?? "").trim().toUpperCase();
  if (t === "NFCE" || t === "NFE") return t;
  return "NFC_E_STUB";
}

function tipoPrecoItem(i: { preco_original: number; preco_unitario: number }): "ATACADO" | "VAREJO" {
  return i.preco_unitario < i.preco_original ? "ATACADO" : "VAREJO";
}

/** Colunas fiscais de `produtos` — mesmo conjunto usado pelo snapshot do caixa web
 * (20260902130000_fiscal_payload_snapshot_venda.sql). B-P0.1 (Onda C1). */
type ProdutoFiscalRow = {
  id: string;
  nome: string | null;
  codigo_barras: string | null;
  ncm: string | null;
  cfop_produto: string | null;
  csosn: string | null;
  cest: string | null;
  cst_pis: string | null;
  cst_cofins: string | null;
  unidade_medida: string | null;
  /** Onda C2.6 (prontidão Focus NFe) — mesmo conjunto do caminho web (20260902140300). */
  icms_origem: string | null;
};

type LojaFiscalRow = {
  id: string;
  cnpj: string | null;
  inscricao_estadual: string | null;
  razao_social: string | null;
  nome_fantasia: string | null;
  endereco_logradouro: string | null;
  endereco_numero: string | null;
  endereco_complemento: string | null;
  endereco_bairro: string | null;
  endereco_cidade: string | null;
  endereco_uf: string | null;
  endereco_cep: string | null;
  cnae: string | null;
  numero_serie_nfce: number | null;
  numero_serie_nfe: number | null;
};

/**
 * Opcional: alinha vendas do PDV local (pós-sync) ao mesmo RPC do caixa web.
 * Desligado por predefinição — exige `AUTO_ENQUEUE_FISCAL_ON_SYNCED_SALE=true` na Edge.
 * Com a flag ligada, falha de leitura ou de RPC rejeita a função para o outbox
 * tentar de novo. A RPC fiscal é upsert por (venda_id, tipo_doc).
 *
 * B-P0.1 (Onda C1, prontidão Focus NFe): o payload passa a incluir a
 * classificação fiscal do produto (ncm/cfop/csosn/cest/cst_pis/cst_cofins) e
 * o emitente (loja), buscados AQUI — uma única vez, no momento do enqueue —
 * e congelados no `payload` de `documentos_fiscais_pendentes`. Depois deste
 * ponto nenhuma alteração posterior em `produtos`/`lojas`/`pdv_config`
 * modifica o documento; o fiscal-worker só lê o payload já persistido.
 */
export async function maybeEnqueueFiscalDocumentAfterSyncedVenda(
  supabase: SupabaseClient,
  payload: VendaPayloadFiscalSync,
  log: (p: Record<string, unknown>) => void,
): Promise<void> {
  const rawFlag = (Deno.env.get("AUTO_ENQUEUE_FISCAL_ON_SYNCED_SALE") ?? "").trim().toLowerCase();
  if (rawFlag !== "true" && rawFlag !== "1") return;

  const tipoDoc = resolveFiscalDocType(Deno.env.get("FISCAL_DEFAULT_DOC_TYPE"));

  let loja_id: string | null = null;
  const caixaId = payload.caixa_id?.trim() ?? "";
  if (isUuid(caixaId)) {
    const { data, error } = await supabase.from("caixas").select("loja_id").eq("id", caixaId).maybeSingle();
    if (error) {
      abortFiscalEnqueue(log, payload.venda_id, `loja_lookup:${error.message}`);
    } else if (data && data.loja_id != null) {
      loja_id = String(data.loja_id);
    }
  }

  const produtoIds = Array.from(
    new Set((payload.itens ?? []).map((i) => i.produto_id).filter((id): id is string => isUuid(id))),
  );

  // Achado de revisão (Codex): erro nesta consulta só era logado como
  // warning e o enqueue continuava com `produtosFiscal` vazio — todo item
  // congelava no snapshot com NCM/CFOP/CSOSN/CEST/CST/`icms_origem` NULL.
  // Como o snapshot é imutável por design (C1), essa incompletude nunca
  // pode ser corrigida depois — o documento fica bloqueado
  // (`FOCUS_DTO_INCOMPLETO`) permanentemente por causa de uma falha
  // TRANSITÓRIA de leitura, exatamente o mesmo padrão já corrigido para
  // `vendas_pagamentos` (P0-2, C2.11). Mesma disciplina aqui: erro ou
  // resultado incompleto (menos produtos do que IDs pedidos) -> fail
  // closed, não enfileira documento fiscal algum nesta rodada.
  const produtosFiscal = new Map<string, ProdutoFiscalRow>();
  if (produtoIds.length > 0) {
    const { data, error } = await supabase
      .from("produtos")
      .select("id, nome, codigo_barras, ncm, cfop_produto, csosn, cest, cst_pis, cst_cofins, unidade_medida, icms_origem")
      .in("id", produtoIds);
    if (error) {
      abortFiscalEnqueue(log, payload.venda_id, `produtos_fiscal_lookup_falhou_fail_closed:${error.message}`);
    }
    for (const row of (data ?? []) as ProdutoFiscalRow[]) produtosFiscal.set(row.id, row);
    if (produtosFiscal.size < produtoIds.length) {
      abortFiscalEnqueue(
        log,
        payload.venda_id,
        `produtos_fiscal_lookup_incompleto_fail_closed:esperado=${produtoIds.length},obtido=${produtosFiscal.size}`,
      );
    }
  }

  // B-P0.1 (gate de completude): data_venda persistida pela RPC de registro
  // de venda do caminho sync (ver o único chamador autorizado, sync-outbox/
  // index.ts) — buscada aqui, não recomputada com `new Date()`, para
  // refletir o instante real da venda.
  let dataVenda: string | null = null;
  {
    const { data, error } = await supabase.from("vendas").select("data").eq("id", payload.venda_id).maybeSingle();
    if (error) {
      log({ level: "warn", stage: "fiscal_enqueue_sync", venda_id: payload.venda_id, detail: `data_venda_lookup:${error.message}` });
    } else if (data?.data) {
      dataVenda = String(data.data);
    }
  }

  // Sprint C2.10 (P0-5): lê `vendas_pagamentos` diretamente — a MESMA fonte
  // (SSOT) que o caminho web já usa em `finalizar_venda_transacional_
  // canonica_v4_unscoped` — em vez de reconstruir um array de 1 elemento a
  // partir do campo escalar `payload.forma_pagamento`. `registrar_venda_
  // com_itens` (Sprint C2.10) grava 1 linha por forma quando o chamador
  // envia `p_pagamentos`, ou 1 única linha (comportamento de sempre) quando
  // não envia — esta leitura reflete corretamente os dois casos sem
  // precisar saber qual caminho a RPC tomou. Nunca deriva split a partir do
  // total; lê o que foi de fato persistido.
  //
  // Sprint C2.11 (P0-2, achado Codex): o fallback anterior ("leitura vazia
  // ou com erro -> reconstrói 1 pagamento escalar a partir do payload de
  // sync") era uma DEGRADAÇÃO SILENCIOSA — podia transformar uma venda
  // mista real em pagamento único no documento fiscal, sem qualquer sinal
  // de que isso aconteceu. `vendas_pagamentos` é a SSOT fiscal (mesma fonte
  // que o caminho web usa sem fallback nenhum); a RPC de registro de venda
  // do caminho sync (sync-outbox/index.ts) SEMPRE grava pelo menos 1 linha
  // quando o total é positivo (branch
  // escalar OU branch de split, nunca os dois ausentes) — então uma leitura
  // vazia ou com erro aqui não é "venda sem pagamento", é sinal de que
  // ALGO deu errado (corrida, permissão, rede) e não há como montar um
  // snapshot fiscal confiável. Fail-closed: a função lança
  // FISCAL_ENFILEIRAR_PENDENTE e o evento volta para retry. A venda já
  // gravada é idempotente; a baixa trata BAIXA_JA_EXISTE como sucesso.
  const { data: pagamentosData, error: pagamentosErr } = await supabase
    .from("vendas_pagamentos")
    .select("forma_pagamento, valor")
    .eq("venda_id", payload.venda_id);
  if (pagamentosErr) {
    abortFiscalEnqueue(log, payload.venda_id, `vendas_pagamentos_lookup_falhou_fail_closed:${pagamentosErr.message}`);
  }
  if (!pagamentosData || pagamentosData.length === 0) {
    abortFiscalEnqueue(log, payload.venda_id, "vendas_pagamentos_vazio_inesperado_fail_closed");
  }
  const pagamentos: Array<{ forma_pagamento: string; valor: number }> = (pagamentosData as Array<{ forma_pagamento: string; valor: number }>)
    .map((p) => ({ forma_pagamento: p.forma_pagamento, valor: roundMoney2(p.valor) }));

  let cfopPadrao: string | null = null;
  let regimeTributario: string | null = null;
  let loja: LojaFiscalRow | null = null;
  if (loja_id) {
    const [{ data: pdvConfigRow, error: pdvConfigErr }, { data: lojaRow, error: lojaErr }] = await Promise.all([
      supabase.from("pdv_config").select("cfop_padrao, regime_tributario").eq("loja_id", loja_id).maybeSingle(),
      supabase
        .from("lojas")
        .select(
          "id, cnpj, inscricao_estadual, razao_social, nome_fantasia, endereco_logradouro, endereco_numero, endereco_complemento, endereco_bairro, endereco_cidade, endereco_uf, endereco_cep, cnae, numero_serie_nfce, numero_serie_nfe",
        )
        .eq("id", loja_id)
        .maybeSingle(),
    ]);
    if (pdvConfigErr) {
      log({ level: "warn", stage: "fiscal_enqueue_sync", venda_id: payload.venda_id, detail: `pdv_config_lookup:${pdvConfigErr.message}` });
    } else if (pdvConfigRow) {
      cfopPadrao = pdvConfigRow.cfop_padrao ?? null;
      regimeTributario = pdvConfigRow.regime_tributario ?? null;
    }
    if (lojaErr) {
      log({ level: "warn", stage: "fiscal_enqueue_sync", venda_id: payload.venda_id, detail: `loja_fiscal_lookup:${lojaErr.message}` });
    } else if (lojaRow) {
      loja = lojaRow as LojaFiscalRow;
    }
  }

  const fiscalPayload = {
    origem: "pdv_local_sync",
    venda_id: payload.venda_id,
    loja_id,
    caixa_id: payload.caixa_id ?? null,
    operador_id: payload.operador_id ?? null,
    data_venda: dataVenda,
    // cliente_id/destinatario: N/A neste caminho — `VendaPayload` do sync-outbox
    // (backend/supabase/functions/sync-outbox/index.ts, tipo `VendaPayload`) não
    // carrega cliente/crédito hoje; não inventado, reportado como gap upstream.
    cliente_id: null,
    destinatario: null,
    // Sprint C2.10 (P0-5): lido de vendas_pagamentos (SSOT) acima — preserva
    // split real quando existir, mesmo formato do caminho web.
    pagamentos,
    totais: {
      bruto: roundMoney2(payload.total_bruto),
      desconto: roundMoney2(payload.total_desconto),
      liquido: roundMoney2(payload.total_liquido),
    },
    itens: (payload.itens ?? []).map((i) => {
      const p = produtosFiscal.get(i.produto_id);
      return {
        produto_id: i.produto_id,
        nome: p?.nome ?? i.nome ?? null,
        codigo_barras: p?.codigo_barras ?? null,
        quantidade: i.quantidade,
        // Sprint C2.11 (P0-2, achado Codex): a chave do snapshot fiscal
        // precisa ser `preco_unitario_original` — é o nome que o caminho
        // web grava (20260902130000_fiscal_payload_snapshot_venda.sql,
        // coluna `itens_venda.preco_unitario_original`) e que `fiscal_focus_
        // dto.ts` (`mapSnapshotItemToFocus`) efetivamente lê para montar
        // `valor_unitario_comercial`. A variável de entrada `i.preco_original`
        // continua com esse nome porque é assim que o pdv-local (Tauri)
        // já envia no payload de sync (`VendaPayloadFiscalSync.itens[].
        // preco_original`) — só a CHAVE DE SAÍDA do snapshot muda, sem
        // mapper/compensação, para que web e sync produzam o mesmo
        // contrato semântico fiscal.
        preco_unitario_original: roundMoney2(i.preco_original),
        preco_unitario: roundMoney2(i.preco_unitario),
        desconto_unitario: roundMoney2(Math.max(0, i.preco_original - i.preco_unitario)),
        tipo_preco: tipoPrecoItem(i),
        unidade_medida: p?.unidade_medida ?? null,
        ncm: p?.ncm ?? null,
        cfop: p?.cfop_produto ?? cfopPadrao,
        csosn: p?.csosn ?? null,
        cest: p?.cest ?? null,
        cst_pis: p?.cst_pis ?? null,
        cst_cofins: p?.cst_cofins ?? null,
        // Onda C2.6: código de origem ICMS, capturado do produto no momento
        // da venda — sem inferência/derivação, NULL quando ainda não
        // classificado (mesmo caminho web, migration 20260902140300).
        icms_origem: p?.icms_origem ?? null,
      };
    }),
    emitente: loja
      ? {
        loja_id: loja.id,
        cnpj: loja.cnpj,
        inscricao_estadual: loja.inscricao_estadual,
        razao_social: loja.razao_social,
        nome_fantasia: loja.nome_fantasia,
        endereco_logradouro: loja.endereco_logradouro,
        endereco_numero: loja.endereco_numero,
        endereco_complemento: loja.endereco_complemento,
        endereco_bairro: loja.endereco_bairro,
        endereco_cidade: loja.endereco_cidade,
        endereco_uf: loja.endereco_uf,
        endereco_cep: loja.endereco_cep,
        cnae: loja.cnae,
        numero_serie_nfce: loja.numero_serie_nfce,
        numero_serie_nfe: loja.numero_serie_nfe,
        regime_tributario: regimeTributario,
      }
      : null,
  };

  const { error: rpcErr } = await supabase.rpc("fiscal_enfileirar_documento_venda", {
    p_venda_id: payload.venda_id,
    p_tipo_doc: tipoDoc,
    p_payload: fiscalPayload,
    p_loja_id: loja_id,  // valida que a venda pertence à loja deste worker (migration 114)
  });

  if (rpcErr) {
    abortFiscalEnqueue(log, payload.venda_id, `rpc:${rpcErr.message}`);
  }
}

// FREEZE: CORE TRANSACIONAL — caller único para registrar_venda_com_itens.
// Não reintroduzir USE_UNIFIED_SALES_FLOW, canary flags ou branches de RPC de venda.
// Ver docs/venda-golden-flow.md para o contrato oficial.
//
// Supabase Edge Function: sync-outbox
// Recebe eventos do PDV local (outbox) e persiste no Postgres.
// Segurança: HMAC (X-SYNC-TS, X-SYNC-NONCE, X-SYNC-SIGNATURE) + X-SYNC-KEY; anti-replay (nonce);
// service role somente no ambiente da Function.
//
// --- Matriz ?op= (após authorizeSync: chave + HMAC + nonce) ---
// | Método | op (query)     | Handler / efeito           | Dados sensíveis na resposta |
// |--------|----------------|----------------------------|-----------------------------|
// | GET    | catalogo       | handleCatalogoSync         | Catálogo: produtos + regras_preco + precos_atacado (Aut#1 / PRICE_RESOLUTION_CHAIN) |
// | GET    | pdv_config     | handlePdvConfigSync        | gerente_id, max_desconto…; strict_manager_auth (sem hash de senha) |
// | GET    | outro/ausente  | —                          | 400 INVALID_OPERATION |
// | POST   | validar_gerente| handleValidarGerentePdvSync| token gerente + expiração (se ok) — token sensível; erros genéricos |
// | POST   | (omitido)      | handlePostOutboxBatch      | processed[], failed[{id,error}], request_id — IDs + mensagens de erro internas |
// |        |                | dispatchOutboxEvent tipos  | Corpo só no POST: VENDA_REGISTRADA (venda+itens), CAIXA_*, MOVIMENTO_CAIXA — persiste no DB; resposta agregada no batch |
// |        |                | pós-venda fiscal (opcional) | Se `AUTO_ENQUEUE_FISCAL_ON_SYNCED_SALE=true`, chama RPC `fiscal_enfileirar_documento_venda`. Falha intermediária rejeita o evento para retry idempotente (venda já registrada retorna; baixa `BAIXA_JA_EXISTE`; fiscal faz upsert). |
// ---

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";
import { timingSafeEqualSecret, timingSafeEqualStr } from "../_shared/crypto.ts";
import { validateGerenteAndIssueToken } from "../_shared/gerente-auth.ts";
import { logJson } from "../_shared/logger.ts";
import { aplicarLojaLegado, assertMesmaLoja, caixaInsertForLoja, requireExplicitLojaId } from "./caixaLoja.ts";
import { maybeEnqueueFiscalDocumentAfterSyncedVenda } from "./fiscal_enqueue_after_venda_sync.ts";
import { captureEdgeException } from "../_shared/sentryEdge.ts";
import {
  assertEventoNoEscopo,
  type DispositivoPdv,
  legacyKeysEnabled,
  normalizarCodigoAtivacao,
  resolveAuthContext,
  type ScopeLookups,
  type SyncContext,
} from "./tenantScope.ts";

type OutboxEvent = {
  id: string;
  tipo: string;
  payload_json: string;
  created_at: string;
};

type SyncRequest = {
  events: OutboxEvent[];
};

type SyncResponse = {
  ok: boolean;
  processed: string[];
  failed: { id: string; error: string }[];
};

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

const MAX_EVENTS_PER_REQUEST = 200;
const MAX_CLOCK_SKEW_SECONDS = 5 * 60;
const NONCE_TTL_SECONDS = 10 * 60;
const CORS_ALLOW_METHODS = "GET, POST, OPTIONS";
const CORS_ALLOW_HEADERS =
  "content-type, x-sync-key, x-sync-ts, x-sync-nonce, x-sync-signature, x-device-fingerprint, x-loja-id";

function hexOfBytes(bytes: Uint8Array): string {
  return Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function hmacSha256Hex(secret: string, message: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, enc.encode(message));
  return hexOfBytes(new Uint8Array(signature));
}

function buildSignaturePayload(
  ts: string,
  nonce: string,
  deviceFingerprint: string,
  body: string,
): string {
  return `${ts}.${nonce}.${deviceFingerprint}.${body}`;
}

/** Valida o body HTTP e normaliza `created_at` ausente. */
function parseSyncRequest(raw: unknown): SyncRequest {
  if (!isRecord(raw) || !Array.isArray(raw.events)) {
    throw new Error("INVALID_BODY");
  }
  if (raw.events.length > MAX_EVENTS_PER_REQUEST) {
    throw new Error(`TOO_MANY_EVENTS: máximo ${MAX_EVENTS_PER_REQUEST}`);
  }
  const events: OutboxEvent[] = [];
  for (const item of raw.events) {
    if (!isRecord(item)) throw new Error("INVALID_EVENT");
    const { id, tipo, payload_json, created_at } = item;
    if (typeof id !== "string" || typeof tipo !== "string" ||
      typeof payload_json !== "string") {
      throw new Error("INVALID_EVENT_FIELDS");
    }
    events.push({
      id,
      tipo,
      payload_json,
      created_at: typeof created_at === "string" ? created_at : "",
    });
  }
  return { events };
}

type VendaItemPayload = {
  item_id?: string;
  produto_id: string;
  nome?: string;
  quantidade: number;
  preco_original: number;
  preco_unitario: number;
};

type VendaPagamentoPayload = { forma_pagamento: string; valor: number };

type VendaPayload = {
  venda_id: string;
  caixa_id?: string | null;
  operador_id?: string | null;
  troco_inicial_caixa?: number | null;
  forma_pagamento: string;
  total_bruto: number;
  total_desconto: number;
  total_liquido: number;
  desconto_gerente_percentual?: number | null;
  desconto_gerente_valor?: number | null;
  desconto_gerente_token?: string | null;
  gerente_id?: string | null;
  itens: VendaItemPayload[];
  loja_id: string;
  /**
   * Sprint C2.10 (P0-5) — split de pagamento opcional. `pdv-local`
   * (cliente desktop Tauri) não captura pagamento misto hoje — sua tabela
   * local `vendas` só tem `forma_pagamento TEXT` escalar
   * (`pdv-local/src-tauri/src/db.rs`) — então este campo fica ausente em
   * todo tráfego real atual, e `registrar_venda_com_itens` cai no
   * comportamento escalar de sempre (1 pagamento = forma_pagamento/
   * total_liquido). Quando o cliente desktop capturar split no futuro
   * (fora desta sprint), basta enviar este campo — nenhuma outra mudança
   * de backend é necessária.
   */
  pagamentos?: VendaPagamentoPayload[] | null;
};

function assertVendaMoneyTotals(raw: Record<string, unknown>): void {
  for (const key of ["total_bruto", "total_desconto", "total_liquido"] as const) {
    const v = raw[key];
    if (typeof v !== "number" || !Number.isFinite(v)) {
      throw new Error(`PAYLOAD_TOTAL_INVALIDO:${key}`);
    }
  }
}

function parseSingleVendaItem(it: unknown): VendaItemPayload {
  if (!isRecord(it)) throw new Error("ITEM_VENDA_INVALIDO");
  const produto_id = it.produto_id;
  if (typeof produto_id !== "string" || !isUuid(produto_id)) {
    throw new Error("ITEM_PRODUTO_ID_INVALIDO");
  }
  const quantidade = Number(it.quantidade);
  const preco_original = Number(it.preco_original);
  const preco_unitario = Number(it.preco_unitario);
  if (!Number.isFinite(quantidade) || quantidade <= 0) {
    throw new Error("ITEM_QUANTIDADE_INVALIDA");
  }
  if (!Number.isFinite(preco_original) || !Number.isFinite(preco_unitario)) {
    throw new Error("ITEM_PRECO_INVALIDO");
  }
  const item: VendaItemPayload = {
    produto_id,
    quantidade,
    preco_original,
    preco_unitario,
  };
  const nome = it.nome;
  const item_id = it.item_id;
  if (typeof nome === "string") item.nome = nome;
  if (typeof item_id === "string" && isUuid(item_id)) item.item_id = item_id;
  return item;
}

function parseVendaItensOrThrow(itensRaw: unknown): VendaItemPayload[] {
  if (!Array.isArray(itensRaw) || itensRaw.length === 0) {
    throw new Error("ERRO_VENDA_SEM_ITENS: payload.itens vazio");
  }
  return itensRaw.map(parseSingleVendaItem);
}

function setCaixaIdFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  if (!("caixa_id" in raw)) return;
  const caixa_id = raw.caixa_id;
  if (caixa_id === null) payload.caixa_id = null;
  else if (typeof caixa_id === "string") payload.caixa_id = caixa_id.trim();
  else throw new Error("PAYLOAD_CAIXA_ID_INVALIDO");
}

function setOperadorIdFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  if (!("operador_id" in raw)) return;
  const operador_id = raw.operador_id;
  if (operador_id === null) payload.operador_id = null;
  else if (typeof operador_id === "string") payload.operador_id = operador_id.trim();
  else throw new Error("PAYLOAD_OPERADOR_ID_INVALIDO");
}

function setTrocoInicialFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  const troco = raw.troco_inicial_caixa;
  if (troco === null || troco === undefined) {
    payload.troco_inicial_caixa = null;
    return;
  }
  if (typeof troco === "number" && Number.isFinite(troco)) {
    payload.troco_inicial_caixa = troco;
    return;
  }
  throw new Error("PAYLOAD_TROCO_CAIXA_INVALIDO");
}

function setDescontoGerenteFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  const dgPct = raw.desconto_gerente_percentual;
  if (dgPct != null) {
    if (typeof dgPct !== "number" || !Number.isFinite(dgPct)) {
      throw new Error("PAYLOAD_DESCONTO_GERENTE_INVALIDO");
    }
    payload.desconto_gerente_percentual = dgPct;
  }
  const dgVal = raw.desconto_gerente_valor;
  if (dgVal != null) {
    if (typeof dgVal !== "number" || !Number.isFinite(dgVal)) {
      throw new Error("PAYLOAD_DESCONTO_GERENTE_INVALIDO");
    }
    payload.desconto_gerente_valor = dgVal;
  }
}

function setGerenteIdFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  const gerente_id = raw.gerente_id;
  if (gerente_id === null || gerente_id === undefined) {
    payload.gerente_id = null;
    return;
  }
  if (typeof gerente_id === "string") {
    payload.gerente_id = gerente_id;
    return;
  }
  throw new Error("PAYLOAD_GERENTE_ID_INVALIDO");
}

function setDescontoTokenFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  if (!("desconto_gerente_token" in raw)) return;
  const token = raw.desconto_gerente_token;
  if (token === null || token === undefined) {
    payload.desconto_gerente_token = null;
    return;
  }
  if (typeof token === "string" && token.trim()) {
    payload.desconto_gerente_token = token.trim();
    return;
  }
  throw new Error("PAYLOAD_DESCONTO_GERENTE_TOKEN_INVALIDO");
}

/** Sprint C2.10 (P0-5) — parse opcional e estrito: se `pagamentos` vier no
 * payload, cada entrada precisa ter forma_pagamento+valor válidos (mesma
 * validação de forma no RPC); malformado = rejeita a venda inteira, nunca
 * ignora silenciosamente uma entrada. Ausente = comportamento escalar. */
function setPagamentosFromPayload(raw: Record<string, unknown>, payload: VendaPayload): void {
  if (!("pagamentos" in raw) || raw.pagamentos == null) return;
  const arr = raw.pagamentos;
  if (!Array.isArray(arr) || arr.length === 0) {
    throw new Error("PAYLOAD_PAGAMENTOS_INVALIDO");
  }
  const pagamentos: VendaPagamentoPayload[] = arr.map((p) => {
    if (!isRecord(p)) throw new Error("PAYLOAD_PAGAMENTOS_INVALIDO");
    const forma = p.forma_pagamento;
    const valor = p.valor;
    if (typeof forma !== "string" || !forma.trim()) throw new Error("PAYLOAD_PAGAMENTOS_INVALIDO");
    if (typeof valor !== "number" || !Number.isFinite(valor) || valor <= 0) throw new Error("PAYLOAD_PAGAMENTOS_INVALIDO");
    return { forma_pagamento: forma.trim(), valor };
  });
  payload.pagamentos = pagamentos;
}

function applyVendaOptionalFields(raw: Record<string, unknown>, payload: VendaPayload): void {
  setCaixaIdFromPayload(raw, payload);
  setOperadorIdFromPayload(raw, payload);
  setTrocoInicialFromPayload(raw, payload);
  setDescontoGerenteFromPayload(raw, payload);
  setGerenteIdFromPayload(raw, payload);
  setDescontoTokenFromPayload(raw, payload);
  setPagamentosFromPayload(raw, payload);
}

function parseVendaPayload(raw: unknown): VendaPayload {
  if (!isRecord(raw)) throw new Error("PAYLOAD_VENDA_INVALIDO");

  const venda_id = raw.venda_id;
  if (typeof venda_id !== "string" || !isUuid(venda_id)) {
    throw new Error("PAYLOAD_VENDA_ID_INVALIDO");
  }

  const forma_pagamento = raw.forma_pagamento;
  if (typeof forma_pagamento !== "string" || !forma_pagamento.trim()) {
    throw new Error("PAYLOAD_FORMA_PAGAMENTO_INVALIDA");
  }

  assertVendaMoneyTotals(raw);
  const itens = parseVendaItensOrThrow(raw.itens);

  const payload: VendaPayload = {
    venda_id,
    forma_pagamento: forma_pagamento.trim(),
    total_bruto: raw.total_bruto as number,
    total_desconto: raw.total_desconto as number,
    total_liquido: raw.total_liquido as number,
    itens,
    loja_id: requireExplicitLojaId(raw.loja_id),
  };

  applyVendaOptionalFields(raw, payload);
  return payload;
}

/** Log estruturado */
const log = (payload: Record<string, unknown>) => logJson("sync-outbox", payload);

function shouldExposeInternalErrors(): boolean {
  const raw = (Deno.env.get("SYNC_OUTBOX_EXPOSE_INTERNAL_ERRORS") ?? "").trim().toLowerCase();
  return raw === "1" || raw === "true" || raw === "yes";
}

/** Sem `SYNC_OUTBOX_EXPOSE_INTERNAL_ERRORS`, ainda retornamos códigos estáveis do contrato sync (CI/diagnóstico). */
function authErrorForClientResponse(code: string, exposeAll: boolean): string {
  if (exposeAll) return code;
  if (
    code === "REPLAY_OR_DB_ERROR" ||
    code === "INVALID_SIG" ||
    code === "TS_OUT_OF_WINDOW"
  ) {
    return code;
  }
  return "UNAUTHORIZED";
}

function newRequestId(): string {
  const bytes = new Uint8Array(12);
  crypto.getRandomValues(bytes);
  return hexOfBytes(bytes);
}

/** Uniforme em [0, 1) via Web Crypto; para gatilhos não adivinháveis por atacante (ex.: throttle de manutenção). */
function secureUnitRandom(): number {
  const buf = new Uint8Array(4);
  crypto.getRandomValues(buf);
  return new DataView(buf.buffer).getUint32(0, false) / 0x100000000;
}

function eventCorrelationId(ev: OutboxEvent): string {
  try {
    if (ev.tipo === "VENDA_REGISTRADA") {
      const parsed = JSON.parse(ev.payload_json) as Record<string, unknown>;
      const vendaId = typeof parsed.venda_id === "string" ? parsed.venda_id.trim() : "";
      if (vendaId) return vendaId;
    }
  } catch {
    // noop: fallback abaixo
  }
  return ev.id;
}

function jsonResponse(req: Request, status: number, body: unknown) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...corsHeaders(req),
    },
  });
}

function corsHeaders(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin") ?? req.headers.get("origin");
  return {
    "Access-Control-Allow-Origin": origin?.trim() || "*",
    "Access-Control-Allow-Methods": CORS_ALLOW_METHODS,
    "Access-Control-Allow-Headers": CORS_ALLOW_HEADERS,
    "Access-Control-Max-Age": "86400",
    Vary: "Origin",
  };
}

function isUuid(s: string | null | undefined): s is string {
  if (!s || typeof s !== "string") return false;
  const t = s.trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    t,
  );
}

function parseCsvLowerSet(raw: string | null | undefined): Set<string> {
  return new Set(
    (raw ?? "")
      .split(",")
      .map((s) => s.trim().toLowerCase())
      .filter((s) => s.length > 0),
  );
}

function parseDeviceKeyMap(raw: string | null | undefined): Map<string, string> {
  const map = new Map<string, string>();
  for (const part of (raw ?? "").split(",")) {
    const [deviceRaw, keyRaw] = part.split("=");
    const device = (deviceRaw ?? "").trim().toLowerCase();
    const key = (keyRaw ?? "").trim();
    if (device && key) map.set(device, key);
  }
  return map;
}

// A Edge usa schema dinâmico do Supabase e o Deno check sem tipos gerados
// produz falsos positivos em `from()/rpc()`. Mantemos o client frouxo aqui.
type SupabaseAdmin = any;

const GERENTE_PDV_IP_LIMIT = 20;
const GERENTE_PDV_DEVICE_LIMIT = 10;
const GERENTE_PDV_GLOBAL_LIMIT = 60;

async function handleValidarGerentePdvSync(
  supabase: SupabaseAdmin,
  rawBody: string,
  req: Request,
  ctx?: SyncContext,
): Promise<Response> {
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return jsonResponse(req, 400, { ok: false, error: "INVALID_JSON" });
  }
  if (!isRecord(body)) {
    return jsonResponse(req, 400, { ok: false, error: "INVALID_BODY" });
  }
  const senhaRaw = body.senha;
  if (typeof senhaRaw !== "string" || !senhaRaw.trim()) {
    return jsonResponse(req, 400, { ok: false, error: "SENHA_OBRIGATORIA" });
  }
  const senhaNormalizada = senhaRaw.trim();
  if (senhaNormalizada.length > 128) {
    return jsonResponse(req, 400, { ok: false, error: "SENHA_INVALIDA_FORMATO" });
  }

  const result = await validateGerenteAndIssueToken({
    supabase,
    senha: senhaNormalizada,
    // Dispositivo ativado: senha de gerente e token presos à loja/empresa do dispositivo (não à Empresa 1).
    lojaId: ctx?.mode === "dispositivo" ? ctx.lojaId : null,
    empresaId: ctx?.mode === "dispositivo" ? ctx.empresaId ?? null : null,
    userId: null,
    req,
    logStage: "validar_gerente_pdv",
    log: log,
    limits: {
      ip: GERENTE_PDV_IP_LIMIT,
      device: GERENTE_PDV_DEVICE_LIMIT,
      global: GERENTE_PDV_GLOBAL_LIMIT,
    },
    tokenCreatedBy: null,
    // Emissor legado (PDV desktop): nunca emite token tipado. Sangria e
    // pagamento AP passam pelo `validar-gerente`, que exige solicitante
    // autenticado para amarrar solicitante/aprovador/loja.
    finalidade: null,
    alvoId: null,
    persistAuthAttemptsByUser: false,
  });
  return jsonResponse(req, result.status, result.body);
}

/**
 * Garante linha em `public.caixas` com o mesmo id da sessão do PDV local
 */
async function ensureCaixaPdv(
  supabase: SupabaseAdmin,
  caixaId: string | null | undefined,
  operadorId: string | null | undefined,
  trocoInicial: number | null | undefined,
  lojaId: unknown,
) {
  if (!isUuid(caixaId)) return;

  const valorInicial =
    trocoInicial != null && Number.isFinite(trocoInicial) ? trocoInicial : 0;
  const op = isUuid(operadorId) ? operadorId.trim() : null;
  const id = caixaId.trim();
  const rowInsert = caixaInsertForLoja({
    id,
    operadorId: op,
    valorInicial,
    lojaId,
  });

  const { data: row, error: selErr } = await supabase
    .from("caixas")
    .select("id,loja_id")
    .eq("id", id)
    .maybeSingle();

  if (selErr) throw new Error(`ERRO_CAIXA_LOOKUP: ${selErr.message}`);
  if (row) {
    assertMesmaLoja(row.loja_id == null ? null : String(row.loja_id), rowInsert.loja_id);
    return;
  }

  const { error: insErr } = await supabase.from("caixas").insert(rowInsert);

  if (insErr && !String(insErr.message).includes("duplicate key")) {
    throw new Error(`ERRO_CAIXA_INSERT: ${insErr.message}`);
  }
}

async function processCaixaAberto(supabase: SupabaseAdmin, ev: OutboxEvent) {
  const p = JSON.parse(ev.payload_json) as {
    id: string;
    operador_id?: string | null;
    valor_inicial?: number;
    loja_id?: unknown;
  };
  const inicial = p.valor_inicial != null && Number.isFinite(p.valor_inicial)
    ? p.valor_inicial
    : 0;
  await ensureCaixaPdv(supabase, p.id, p.operador_id ?? null, inicial, p.loja_id);
}

async function processCaixaFechado(supabase: SupabaseAdmin, ev: OutboxEvent) {
  // BA-010: SSoT de fechamento PDV Local = RPC fechar_caixa_pdv_atomico (migração 227).
  // Não recalcular valor_sistema nem UPDATE direto — evita divergência com o fechamento atômico.
  const p = JSON.parse(ev.payload_json) as {
    id: string;
    data_fechamento: string;
    valor_fechamento: number;
    fechamento_observacao?: string | null;
  };
  if (!isUuid(p.id)) throw new Error("CAIXA_FECHADO_ID_INVALIDO");
  if (typeof p.data_fechamento !== "string" || !p.data_fechamento) {
    throw new Error("CAIXA_FECHADO_DATA_INVALIDA");
  }

  const valorFechamento =
    typeof p.valor_fechamento === "number" && Number.isFinite(p.valor_fechamento)
      ? p.valor_fechamento
      : 0;

  let fechamentoObs: string | null = null;
  if (typeof p.fechamento_observacao === "string") {
    const t = p.fechamento_observacao.trim();
    if (t.length > 500) throw new Error("CAIXA_FECHADO_OBSERVACAO_LONGA");
    fechamentoObs = t.length > 0 ? t : null;
  }

  const caixaId = p.id.trim();
  const { error } = await supabase.rpc("fechar_caixa_pdv_atomico", {
    p_caixa_id: caixaId,
    p_valor_contado: valorFechamento,
    p_observacao: fechamentoObs,
    p_data_fechamento: p.data_fechamento,
  });

  if (!error) return;

  const msg = error.message ?? "";
  // Replay idempotente: outbox reenvia CAIXA_FECHADO após sucesso (comportamento do UPDATE antigo 0 rows).
  if (msg.includes("FECHAR_CAIXA_PDV_NAO_ENCONTRADO")) {
    const { data: row, error: readErr } = await supabase
      .from("caixas")
      .select("status")
      .eq("id", caixaId)
      .maybeSingle();
    if (readErr) throw new Error(`ERRO_CAIXA_FECHADO: ${readErr.message}`);
    if (row && (row as { status?: string }).status === "FECHADO") return;
  }

  throw new Error(`ERRO_CAIXA_FECHADO: ${msg}`);
}

async function processMovimentoCaixa(supabase: SupabaseAdmin, ev: OutboxEvent) {
  const p = JSON.parse(ev.payload_json) as {
    id: string;
    caixa_id: string;
    tipo: string;
    valor: number;
    observacao?: string | null;
    created_at?: string;
  };
  if (!isUuid(p.id)) throw new Error("MOVIMENTO_ID_INVALIDO");
  if (!isUuid(p.caixa_id)) throw new Error("MOVIMENTO_CAIXA_ID_INVALIDO");
  if (typeof p.valor !== "number" || !Number.isFinite(p.valor)) {
    throw new Error("MOVIMENTO_VALOR_INVALIDO");
  }
  if (p.tipo !== "SANGRIA" && p.tipo !== "SUPRIMENTO") {
    throw new Error(`TIPO_MOVIMENTO_INVALIDO: ${p.tipo}`);
  }

  const caixaId = p.caixa_id.trim();
  const { data: caixaRow, error: caixaErr } = await supabase
    .from("caixas")
    .select("operador_id")
    .eq("id", caixaId)
    .maybeSingle();

  if (caixaErr) throw new Error(`MOVIMENTO_CAIXA_LOOKUP: ${caixaErr.message}`);
  const operadorId = caixaRow?.operador_id;
  if (!operadorId || !isUuid(String(operadorId))) {
    throw new Error("MOVIMENTO_CAIXA_OPERADOR_OBRIGATORIO");
  }

  const tipoMovimento = p.tipo === "SANGRIA" ? "sangria" : "suprimento";
  const motivo =
    typeof p.observacao === "string" && p.observacao.trim().length > 0
      ? p.observacao.trim()
      : "Movimento sincronizado (PDV local)";

  const { error } = await supabase.rpc("registrar_movimentacao", {
    p_caixa_id: caixaId,
    p_tipo: tipoMovimento,
    p_forma_pagamento: "dinheiro",
    p_valor: p.valor,
    p_motivo: motivo,
    p_motivo_codigo: "OUTRO",
    p_status: null,
    p_movimentacao_origem_id: null,
    p_idempotency_key: p.id.trim(),
    p_ip_address: null,
    p_user_agent: null,
    p_device_id: null,
    p_terminal_id: "sync-outbox",
    p_operador_id: String(operadorId).trim(),
    p_gerente_id: null,
  });

  if (error && !String(error.message).includes("duplicate key")) {
    throw new Error(`ERRO_MOVIMENTO: ${error.message}`);
  }
}

async function aplicarBaixaEstoquePorItem(
  supabase: SupabaseAdmin,
  vendaId: string,
  itens: Array<{ produto_id: string; quantidade: number }>,
) {
  const errosEstoque: string[] = [];

  for (const i of itens ?? []) {
    if (!isUuid(i.produto_id)) continue;
    const qty = Number(i.quantidade);
    if (!Number.isFinite(qty) || qty <= 0) continue;

    const { data: estoqueResult, error: rpcErr } = await supabase.rpc(
      "decrementar_estoque_seguro",
      {
        p_produto_id: i.produto_id.trim(),
        p_quantidade: qty,
        p_venda_id: vendaId,
      },
    );

    if (rpcErr) {
      errosEstoque.push(`Produto ${i.produto_id}: ${rpcErr.message}`);
      continue;
    }

    if (estoqueResult?.[0] && !estoqueResult[0].sucesso) {
      errosEstoque.push(`Produto ${i.produto_id}: ${estoqueResult[0].mensagem}`);
    }
  }

  const errosCriticos = errosEstoque.filter((e) => !e.includes("BAIXA_JA_EXISTE"));
  if (errosCriticos.length > 0) {
    throw new Error(`ERRO_ESTOQUE: ${errosCriticos.join("; ")}`);
  }
}

async function processVenda(
  supabase: SupabaseAdmin,
  ev: OutboxEvent,
) {
  const parsedJson = JSON.parse(ev.payload_json);
  const payload = parseVendaPayload(parsedJson);
  const strictManagerDiscountAuth = Deno.env.get("STRICT_MANAGER_DISCOUNT_AUTH") === "true";
  const _t0 = Date.now();

  await ensureCaixaPdv(
    supabase,
    payload.caixa_id,
    payload.operador_id,
    payload.troco_inicial_caixa ?? null,
    payload.loja_id,
  );

  const hasManagerDiscount = (payload.desconto_gerente_percentual ?? 0) > 0 ||
    (payload.desconto_gerente_valor ?? 0) > 0;
  if (strictManagerDiscountAuth && hasManagerDiscount && !payload.desconto_gerente_token) {
    throw new Error("GERENTE_TOKEN_OBRIGATORIO");
  }

  const { error: rpcVendaErr } = await supabase.rpc("registrar_venda_com_itens", {
    p_venda_id: payload.venda_id,
    p_caixa_id: payload.caixa_id,
    p_operador_id: payload.operador_id,
    p_forma_pagamento: payload.forma_pagamento,
    p_total_bruto: payload.total_bruto,
    p_total_desconto: payload.total_desconto,
    p_total_liquido: payload.total_liquido,
    p_itens: payload.itens ?? [],
    p_desconto_gerente_percentual: payload.desconto_gerente_percentual ?? null,
    p_desconto_gerente_valor: payload.desconto_gerente_valor ?? null,
    p_gerente_id: payload.gerente_id ?? null,
    // Sprint C2.10 (P0-5): null em todo tráfego real hoje (pdv-local não
    // envia) -> RPC cai no comportamento escalar de sempre, sem mudança.
    p_pagamentos: payload.pagamentos ?? null,
  });

  if (rpcVendaErr) {
    await captureEdgeException(new Error(rpcVendaErr.message), {
      trace_id: payload.venda_id,
      venda_id: payload.venda_id,
      caixa_id: payload.caixa_id ?? undefined,
      evento: "erro_rpc_venda",
      rpc: "registrar_venda_com_itens",
      event_type: "VENDA_REGISTRADA",
    });
    throw new Error(`ERRO_RPC_REGISTRAR_VENDA: ${rpcVendaErr.message}`);
  }

  const { error: ledgerErr } = await supabase.rpc("ensure_venda_evento_registrado", {
    p_sale_id: payload.venda_id,
    p_source: "sync_outbox",
  });
  if (ledgerErr) {
    throw new Error(`ERRO_RPC_REGISTRAR_VENDA_EVENTO: ${ledgerErr.message}`);
  }
  const _t1 = Date.now();

  await aplicarBaixaEstoquePorItem(
    supabase,
    payload.venda_id,
    (payload.itens ?? []).map((i) => ({ produto_id: i.produto_id, quantidade: i.quantidade })),
  );
  const _t2 = Date.now();

  await maybeEnqueueFiscalDocumentAfterSyncedVenda(supabase, payload, log);

  log({
    level: "info",
    stage: "venda_registrada",
    path: "sync_outbox",
    rpc: "registrar_venda_com_itens",
    venda_id: payload.venda_id,
    steps: {
      rpc_ms: _t1 - _t0,
      estoque_ms: _t2 - _t1,
      total_ms: Date.now() - _t0,
    },
  });
}

function parseLojaIdHeader(req: Request): string | null {
  const raw = (req.headers.get("x-loja-id") ?? "").trim();
  if (!raw) {
    const fromEnv = (Deno.env.get("DEFAULT_PDV_LOJA_ID") ?? "").trim();
    return fromEnv.length > 0 ? fromEnv : null;
  }
  return raw;
}

async function handleCatalogoSync(req: Request, supabase: SupabaseAdmin, ctx: SyncContext) {
  // Aut#1: precos_atacado como array canônico (não projetar em regras_preco).
  // Multiempresa: dispositivo ativado ⇒ catálogo SÓ da loja do dispositivo (loja vinda do servidor).
  const lojaId = ctx.mode === "dispositivo" ? ctx.lojaId : parseLojaIdHeader(req);
  let produtosQuery = supabase
    .from("produtos")
    .select(
      "id,nome,codigo_barras,preco_varejo,preco_atacado,categoria_id,ativo,status_publicacao,origem,tem_nf,imagem_url",
    );
  if (ctx.mode === "dispositivo") produtosQuery = produtosQuery.eq("loja_id", ctx.lojaId);
  const REGRAS_COLS =
    "id,tipo_regra,produto_id,categoria_id,quantidade_minima,quantidade_maxima,tipo_desconto,valor_desconto,data_validade,ativo";
  const regrasDaEmpresa = async () => {
    // Fase 2+: regras_preco tem empresa_id ⇒ dispositivo recebe só as da própria empresa (inclui regras gerais).
    if (ctx.mode !== "dispositivo" || !ctx.empresaId) {
      return await supabase.from("regras_preco").select(REGRAS_COLS).eq("ativo", true).limit(100000);
    }
    const r = await supabase.from("regras_preco").select(`${REGRAS_COLS},empresa_id`).eq("ativo", true)
      .eq("empresa_id", ctx.empresaId).limit(100000);
    if (r.error && /empresa_id/.test(r.error.message)) {
      return await supabase.from("regras_preco").select(REGRAS_COLS).eq("ativo", true).limit(100000);
    }
    return r;
  };
  const [produtosRes, regrasRes, atacadoRes] = await Promise.all([
    produtosQuery
      .order("nome", { ascending: true })
      .limit(100000),
    regrasDaEmpresa(),
    supabase
      .from("precos_atacado")
      .select("id,produto_id,loja_id,quantidade_minima,preco_unitario,ativo")
      .eq("ativo", true)
      .limit(100000),
  ]);

  if (produtosRes.error) throw new Error(`ERRO_CATALOGO_PRODUTOS: ${produtosRes.error.message}`);
  if (regrasRes.error) throw new Error(`ERRO_CATALOGO_REGRAS: ${regrasRes.error.message}`);
  if (atacadoRes.error) throw new Error(`ERRO_CATALOGO_PRECOS_ATACADO: ${atacadoRes.error.message}`);

  const precosAtacado = ((atacadoRes.data ?? []) as Array<{
    id: string;
    produto_id: string;
    loja_id: string | null;
    quantidade_minima: number;
    preco_unitario: number;
    ativo: boolean;
  }>).filter((row) => {
    const lid = row.loja_id;
    return lid == null || (lojaId != null && lid === lojaId);
  });

  const produtos = (produtosRes.data ?? []) as Array<{ id: string; categoria_id?: string | null }>;
  let regras = (regrasRes.data ?? []) as Array<{ produto_id?: string | null; categoria_id?: string | null }>;
  let atacadoFiltrado = precosAtacado;
  if (ctx.mode === "dispositivo") {
    // regras_preco/precos_atacado ainda não têm empresa_id (D12, etapa 6): restringe pelos produtos/categorias
    // da loja. Regra sem produto e sem categoria (global) não é enviada a dispositivos de tenant.
    const prodIds = new Set(produtos.map((p) => p.id));
    const catIds = new Set(produtos.map((p) => p.categoria_id).filter((c): c is string => !!c));
    const porEmpresa = regras.length > 0 && regras.every((r) => "empresa_id" in r);
    regras = regras.filter((r) =>
      (r.produto_id != null && prodIds.has(r.produto_id)) ||
      (r.produto_id == null && r.categoria_id != null && catIds.has(r.categoria_id)) ||
      // regra geral (sem produto/categoria) só quando já veio filtrada pela empresa do dispositivo
      (porEmpresa && r.produto_id == null && r.categoria_id == null)
    ).map((r) => {
      const { empresa_id: _e, ...resto } = r as Record<string, unknown>;
      return resto as typeof r;
    });
    atacadoFiltrado = precosAtacado.filter((r) => prodIds.has(r.produto_id));
  }

  return jsonResponse(req, 200, {
    ok: true,
    produtos,
    regras,
    precos_atacado: atacadoFiltrado,
    loja_id: lojaId,
  });
}

async function handlePdvConfigSync(req: Request, supabase: SupabaseAdmin, ctx: SyncContext) {
  const lojaId = ctx.mode === "dispositivo" ? ctx.lojaId : parseLojaIdHeader(req);
  const base = supabase
    .from("pdv_config")
    .select("gerente_id, max_desconto_gerente_percentual, quantidade_minima_atacado_padrao");
  // legado: linha id=1 (cliente 1, inalterado). Dispositivo: config da própria loja.
  let { data, error, status } = await (ctx.mode === "dispositivo"
    ? base.eq("loja_id", ctx.lojaId)
    : base.eq("id", 1)).maybeSingle();
  // Dispositivo sem linha própria da loja ⇒ linha padrão da EMPRESA do dispositivo (fase 3), nunca a de outra.
  if (!error && !data && ctx.mode === "dispositivo" && ctx.empresaId) {
    const padrao = await supabase
      .from("pdv_config")
      .select("gerente_id, max_desconto_gerente_percentual, quantidade_minima_atacado_padrao")
      .is("loja_id", null)
      .eq("empresa_id", ctx.empresaId)
      .maybeSingle();
    if (!padrao.error) data = padrao.data;
  }

  if (error) {
    if (status === 404 || status === 400) return jsonResponse(req, 200, { ok: true, config: null });
    throw new Error(`ERRO_PDV_CONFIG: ${error.message}`);
  }

  const configComFlag = data
    ? {
      ...data,
      loja_id: lojaId,
      strict_manager_auth: Deno.env.get("STRICT_MANAGER_DISCOUNT_AUTH") === "true",
    }
    : null;

  return jsonResponse(req, 200, { ok: true, config: configComFlag });
}

async function handleGetByOp(
  req: Request,
  op: string | null,
  supabase: SupabaseAdmin,
  ctx: SyncContext,
): Promise<Response | null> {
  if (op === "catalogo") return await handleCatalogoSync(req, supabase, ctx);
  if (op === "pdv_config") return await handlePdvConfigSync(req, supabase, ctx);
  return null;
}

function publicBatchError(err: string, exposeInternalErrors: boolean): string {
  if (exposeInternalErrors) return err;
  return "EVENT_PROCESSING_FAILED";
}

function scopeLookups(supabase: SupabaseAdmin): ScopeLookups {
  return {
    caixaLoja: async (caixaId: string) => {
      const { data, error } = await supabase.from("caixas").select("loja_id").eq("id", caixaId).maybeSingle();
      if (error) throw new Error(`ESCOPO_CAIXA_LOOKUP: ${error.message}`);
      return data?.loja_id == null ? null : String(data.loja_id);
    },
    produtosForaDaLoja: async (ids: string[], lojaId: string) => {
      const { data, error } = await supabase.from("produtos").select("id,loja_id").in("id", ids);
      if (error) throw new Error(`ESCOPO_PRODUTOS_LOOKUP: ${error.message}`);
      const daLoja = new Set(((data ?? []) as Array<{ id: string; loja_id: string }>)
        .filter((r) => String(r.loja_id) === lojaId).map((r) => String(r.id)));
      return ids.filter((id) => !daLoja.has(id)).length;
    },
    operadorPodeLoja: async (operadorId: string, lojaId: string) => {
      const { data, error } = await supabase.rpc("fp_usuario_pode_loja", { p_usuario: operadorId, p_loja: lojaId });
      if (error) throw new Error(`ESCOPO_OPERADOR_LOOKUP: ${error.message}`);
      return data === true;
    },
  };
}

async function dispatchOutboxEvent(
  supabase: SupabaseAdmin,
  ev: OutboxEvent,
  ctx: SyncContext,
): Promise<void> {
  if (ctx.mode === "legado") {
    const r = await aplicarLojaLegado(ev, ctx.lojaId, {
      caixaLoja: scopeLookups(supabase).caixaLoja,
      lojasAtivas: async () => {
        const { data, error } = await supabase.from("lojas").select("id").eq("ativo", true).limit(2);
        if (error) throw new Error(`LOJA_LEGADO_LOOKUP: ${error.message}`);
        return ((data ?? []) as Array<{ id: string }>).map((l) => String(l.id));
      },
    });
    if (r.auditoria) {
      log({ level: "warn", stage: "loja_legado_resolvida", event_id: (ev as { id?: string }).id, event_type: ev.tipo, ...r.auditoria });
      ev = r.ev;
    }
  }
  await assertEventoNoEscopo(ev, ctx, scopeLookups(supabase));
  if (ev.tipo === "VENDA_REGISTRADA") await processVenda(supabase, ev);
  else if (ev.tipo === "CAIXA_ABERTO") await processCaixaAberto(supabase, ev);
  else if (ev.tipo === "CAIXA_FECHADO") await processCaixaFechado(supabase, ev);
  else if (ev.tipo === "MOVIMENTO_CAIXA") await processMovimentoCaixa(supabase, ev);
  else throw new Error(`TIPO_DESCONHECIDO: ${ev.tipo}`);
}

async function handlePostOutboxBatch(
  supabase: SupabaseAdmin,
  rawBody: string,
  req: Request,
  requestId: string,
  reqStart: number,
  exposeInternalErrors: boolean,
  ctx: SyncContext,
): Promise<Response> {
  let body: SyncRequest;
  try {
    body = parseSyncRequest(JSON.parse(rawBody));
  } catch (e) {
    const err = e instanceof Error ? e.message : "INVALID_JSON";
    return jsonResponse(req, 400, { ok: false, error: err, request_id: requestId });
  }

  const processed: string[] = [];
  const failed: { id: string; error: string }[] = [];
  log({
    level: "info",
    stage: "sync_start",
    request_id: requestId,
    event_count: body.events.length,
  });

  for (const ev of body.events) {
    try {
      await dispatchOutboxEvent(supabase, ev, ctx);
      processed.push(ev.id);
      log({
        level: "info",
        stage: "event_processed",
        request_id: requestId,
        event_id: ev.id,
        event_type: ev.tipo,
        correlation_id: eventCorrelationId(ev),
      });
    } catch (e) {
      const rawErr = e instanceof Error ? e.message : String(e);
      failed.push({ id: ev.id, error: publicBatchError(rawErr, exposeInternalErrors) });
      log({
        level: "warn",
        stage: "event_failed",
        request_id: requestId,
        event_id: ev.id,
        event_type: ev.tipo,
        correlation_id: eventCorrelationId(ev),
        error: rawErr,
      });
      await captureEdgeException(e, {
        trace_id: eventCorrelationId(ev),
        evento: "erro_sync_outbox",
        event_type: ev.tipo,
        request_id: requestId,
      });
    }
  }

  log({
    level: "info",
    stage: "sync_end",
    request_id: requestId,
    processed_count: processed.length,
    failed_count: failed.length,
    duration_ms: Date.now() - reqStart,
  });
  return jsonResponse(req, 200, { ok: true, processed, failed, request_id: requestId });
}

Deno.serve(async (req) => {
  const requestId = newRequestId();
  const reqStart = Date.now();
  const exposeInternalErrors = shouldExposeInternalErrors();
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: corsHeaders(req) });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL")?.trim() ?? "";
  const serviceRole = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")?.trim() ?? "";
  const syncKey = Deno.env.get("SYNC_KEY")?.trim() ?? "";
  if (!supabaseUrl || !serviceRole) {
    log({ level: "error", stage: "env", request_id: requestId, error: "MISSING_SUPABASE_ENV" });
    return jsonResponse(req, 500, { ok: false, error: "MISSING_SUPABASE_ENV", request_id: requestId });
  }

  const url = new URL(req.url);
  const op = url.searchParams.get("op");
  const supabase = createClient(supabaseUrl, serviceRole, {
    auth: { persistSession: false },
  });

  const rawBody = req.method === "POST" ? await req.text() : "";

  // Ativação por código (antes do HMAC: o PDV ainda não tem segredo). Código de uso único, 24h, hash no banco.
  if (req.method === "POST" && op === "ativar") {
    return await handleAtivarDispositivo(req, supabase, rawBody, requestId);
  }

  const auth = await authorizeSync(req, syncKey, supabase, rawBody);
  if (!auth.ok || !auth.ctx) {
    log({
      level: "warn",
      stage: "auth",
      request_id: requestId,
      error: auth.error,
    });
    const authError = authErrorForClientResponse(
      auth.error ?? "UNAUTHORIZED",
      exposeInternalErrors,
    );
    return jsonResponse(req, 401, { ok: false, error: authError, request_id: requestId });
  }

  try {
    if (req.method === "GET") {
      const getRes = await handleGetByOp(req, op, supabase, auth.ctx);
      if (getRes) return getRes;
      return jsonResponse(req, 400, { ok: false, error: "INVALID_OPERATION", request_id: requestId });
    }

    if (req.method === "POST") {
      if (op === "validar_gerente") {
        return await handleValidarGerentePdvSync(
          supabase,
          rawBody,
          req,
          auth.ctx,
        );
      }
      return await handlePostOutboxBatch(
        supabase,
        rawBody,
        req,
        requestId,
        reqStart,
        exposeInternalErrors,
        auth.ctx,
      );
    }

    return jsonResponse(req, 400, { ok: false, error: "INVALID_OPERATION", request_id: requestId });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    log({
      level: "error",
      stage: "sync_fatal",
      request_id: requestId,
      error: msg,
      duration_ms: Date.now() - reqStart,
    });
    return jsonResponse(req, 500, {
      ok: false,
      error: "ERRO_INTERNO",
      request_id: requestId,
    });
  }
});

/** Limpeza oportunista (~3% das requisições autenticadas) para manter a tabela pequena sem job dedicado. */
async function maybePruneExpiredSyncNonces(supabase: SupabaseAdmin): Promise<void> {
  if (secureUnitRandom() >= 0.03) return;
  const nowIso = new Date().toISOString();
  const { error } = await supabase.from("sync_request_nonces").delete().lt("expires_at", nowIso);
  if (error) {
    log({ level: "warn", stage: "nonce_prune", error: error.message });
  }
}

const ATIVACAO_ERROS_PUBLICOS = new Set([
  "ATIVACAO_PDV_CODIGO_INVALIDO",
  "ATIVACAO_PDV_FINGERPRINT_INVALIDO",
  "EMPRESA_NAO_OPERACIONAL",
  "ATIVACAO_PDV_BLOQUEADA",
]);

function ipDaRequisicao(req: Request): string | null {
  const fwd = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  return (fwd || req.headers.get("x-real-ip")?.trim() || null)?.slice(0, 64) ?? null;
}

async function handleAtivarDispositivo(
  req: Request,
  supabase: SupabaseAdmin,
  rawBody: string,
  requestId: string,
): Promise<Response> {
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return jsonResponse(req, 400, { ok: false, error: "INVALID_JSON", request_id: requestId });
  }
  if (!isRecord(body)) return jsonResponse(req, 400, { ok: false, error: "INVALID_BODY", request_id: requestId });
  const codigo = normalizarCodigoAtivacao(body.codigo);
  const fp = typeof body.device_fingerprint === "string" ? body.device_fingerprint.trim().toLowerCase() : "";
  if (!codigo) return jsonResponse(req, 400, { ok: false, error: "ATIVACAO_PDV_CODIGO_INVALIDO", request_id: requestId });
  if (fp.length < 3 || fp.length > 200) {
    return jsonResponse(req, 400, { ok: false, error: "ATIVACAO_PDV_FINGERPRINT_INVALIDO", request_id: requestId });
  }
  const nome = typeof body.nome === "string" ? body.nome.trim().slice(0, 80) : null;
  // v2: registra a tentativa e bloqueia após 10 falhas/15 min por computador ou IP (anti força-bruta).
  const { data, error } = await supabase.rpc("ativar_dispositivo_pdv_v2", {
    p_codigo: codigo,
    p_device_fingerprint: fp,
    p_nome: nome,
    p_ip: ipDaRequisicao(req),
  });
  if (!error && data && data.ok === false) {
    const code = ATIVACAO_ERROS_PUBLICOS.has(String(data.error)) ? String(data.error) : "ATIVACAO_PDV_CODIGO_INVALIDO";
    log({ level: "warn", stage: "ativar_pdv", request_id: requestId, error: code });
    return jsonResponse(req, code === "ATIVACAO_PDV_BLOQUEADA" ? 429 : 400, { ok: false, error: code, request_id: requestId });
  }
  if (error) {
    const code = [...ATIVACAO_ERROS_PUBLICOS].find((c) => String(error.message).includes(c)) ?? "ATIVACAO_PDV_FALHOU";
    log({ level: "warn", stage: "ativar_pdv", request_id: requestId, error: code });
    return jsonResponse(req, code === "ATIVACAO_PDV_FALHOU" ? 500 : 400, { ok: false, error: code, request_id: requestId });
  }
  log({ level: "info", stage: "ativar_pdv", request_id: requestId, dispositivo_id: data?.dispositivo_id, loja_id: data?.loja_id });
  return jsonResponse(req, 200, { ok: true, ...data, request_id: requestId });
}

async function lookupDispositivo(supabase: SupabaseAdmin, device: string): Promise<DispositivoPdv | null> {
  const { data, error } = await supabase
    .from("pdv_dispositivos")
    .select("id,loja_id,empresa_id,sync_secret")
    .eq("device_fingerprint", device)
    .eq("ativo", true)
    .maybeSingle();
  // Tabela ausente (migration ainda não aplicada) ⇒ cai no modo legado, sem quebrar o cliente 1.
  if (error) {
    log({ level: "warn", stage: "dispositivo_lookup", error: error.message });
    return null;
  }
  return data ? (data as DispositivoPdv) : null;
}

async function authorizeSync(
  req: Request,
  syncKey: string,
  supabase: SupabaseAdmin,
  rawBody: string,
): Promise<{ ok: boolean; error?: string; ctx?: SyncContext }> {
  const gotKey = req.headers.get("X-SYNC-KEY")?.trim();
  const ts = req.headers.get("X-SYNC-TS");
  const nonce = req.headers.get("X-SYNC-NONCE");
  const signature = req.headers.get("X-SYNC-SIGNATURE");
  const device = (req.headers.get("x-device-fingerprint") ?? "").trim().toLowerCase();
  const enforceAllowlist = (Deno.env.get("SYNC_ENFORCE_DEVICE_ALLOWLIST") ?? "auto").trim().toLowerCase();
  const allowedDevices = parseCsvLowerSet(Deno.env.get("SYNC_ALLOWED_DEVICE_FINGERPRINTS"));
  const deviceKeyMap = parseDeviceKeyMap(Deno.env.get("SYNC_DEVICE_KEYS"));
  const shouldEnforceAllowlist =
    enforceAllowlist === "true" ||
    enforceAllowlist === "1" ||
    enforceAllowlist === "yes" ||
    ((enforceAllowlist === "auto" || enforceAllowlist === "") && allowedDevices.size > 0);

  if (!ts || !nonce || !signature) return { ok: false, error: "MISSING_HEADERS" };
  if (!device) return { ok: false, error: "MISSING_DEVICE_FINGERPRINT" };
  const dispositivo = await lookupDispositivo(supabase, device);
  // dispositivo ativado por código dispensa a allowlist do ambiente (ele já é a allowlist, no banco).
  if (shouldEnforceAllowlist && !dispositivo && !allowedDevices.has(device)) {
    return { ok: false, error: "DEVICE_NOT_ALLOWED" };
  }
  const legacyKey = deviceKeyMap.size > 0 ? deviceKeyMap.get(device) ?? null : (syncKey || null);
  const resolved = resolveAuthContext({
    dispositivo,
    headerLojaId: (req.headers.get("x-loja-id") ?? "").trim() || null,
    legacyEnabled: legacyKeysEnabled(Deno.env.get("SYNC_LEGACY_KEYS_ENABLED")),
    legacyKey,
  });
  if (!resolved.ok) return { ok: false, error: resolved.error };
  const expectedKey = resolved.expectedKey;
  if (!gotKey || !(await timingSafeEqualSecret(gotKey, expectedKey))) {
    return { ok: false, error: "UNAUTHORIZED" };
  }
  const nonceTrim = nonce.trim();
  if (!isUuid(nonceTrim)) return { ok: false, error: "INVALID_NONCE" };

  const tsNum = Number(ts);
  if (!Number.isFinite(tsNum)) return { ok: false, error: "INVALID_TS" };
  if (Math.abs(Math.floor(Date.now() / 1000) - tsNum) > MAX_CLOCK_SKEW_SECONDS) return { ok: false, error: "TS_OUT_OF_WINDOW" };

  const payload = buildSignaturePayload(ts, nonceTrim, device, rawBody);
  const expectedSig = await hmacSha256Hex(expectedKey, payload);
  if (!timingSafeEqualStr(signature.toLowerCase(), expectedSig.toLowerCase())) return { ok: false, error: "INVALID_SIG" };

  const expiresAt = new Date((tsNum + NONCE_TTL_SECONDS) * 1000).toISOString();
  const { error } = await supabase.from("sync_request_nonces").insert({
    nonce: nonceTrim,
    device_fingerprint: device,
    request_ts: tsNum,
    expires_at: expiresAt,
  });
  if (error) return { ok: false, error: "REPLAY_OR_DB_ERROR" };

  try {
    await maybePruneExpiredSyncNonces(supabase);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    log({ level: "warn", stage: "nonce_prune_fatal", error: msg });
  }

  if (resolved.ctx.mode === "dispositivo") {
    const { error: touchErr } = await supabase
      .from("pdv_dispositivos")
      .update({ ultimo_sync_em: new Date().toISOString() })
      .eq("id", resolved.ctx.dispositivoId);
    if (touchErr) log({ level: "warn", stage: "dispositivo_touch", error: touchErr.message });
  }

  return { ok: true, ctx: resolved.ctx };
}

// Escopo de tenant do sync-outbox (ESPEC_MULTIEMPRESA_V1 §11 / D6).
//
// Dois modos de autenticação:
//  * "dispositivo": PDV ativado por código (tabela pdv_dispositivos). O segredo HMAC é POR DISPOSITIVO
//    e a loja vem do SERVIDOR (pdv_dispositivos.loja_id). Header x-loja-id e loja do payload só podem
//    confirmar essa loja — nunca escolher outra. Obrigatório para o cliente 2 em diante.
//  * "legado": SYNC_KEY / SYNC_DEVICE_KEYS do ambiente (cliente 1, comportamento inalterado — D10).
//    Desligável com SYNC_LEGACY_KEYS_ENABLED=false quando todos os PDVs estiverem ativados.

export type DispositivoPdv = {
  id: string;
  loja_id: string;
  empresa_id: string;
  sync_secret: string;
};

export type SyncContext =
  | { mode: "dispositivo"; lojaId: string; empresaId: string; dispositivoId: string }
  | { mode: "legado"; lojaId: string | null };

export type ScopeLookups = {
  /** loja_id do caixa no servidor, ou null se o caixa não existe. */
  caixaLoja: (caixaId: string) => Promise<string | null>;
  /** quantos produtos da lista NÃO pertencem à loja. */
  produtosForaDaLoja: (produtoIds: string[], lojaId: string) => Promise<number>;
  /** O operador tem vínculo ativo que cobre a loja (fp_usuario_pode_loja)? */
  operadorPodeLoja: (operadorId: string, lojaId: string) => Promise<boolean>;
};

export function legacyKeysEnabled(raw: string | undefined | null): boolean {
  const v = (raw ?? "").trim().toLowerCase();
  return !(v === "false" || v === "0" || v === "no");
}

/** Decide a chave esperada e o contexto, ANTES de validar a assinatura. */
export function resolveAuthContext(input: {
  dispositivo: DispositivoPdv | null;
  headerLojaId: string | null;
  legacyEnabled: boolean;
  legacyKey: string | null;
}):
  | { ok: true; expectedKey: string; ctx: SyncContext }
  | { ok: false; error: string } {
  const header = input.headerLojaId?.trim() || null;
  if (input.dispositivo) {
    if (header && header !== input.dispositivo.loja_id) {
      return { ok: false, error: "LOJA_DIVERGENTE_DO_DISPOSITIVO" };
    }
    return {
      ok: true,
      expectedKey: input.dispositivo.sync_secret,
      ctx: {
        mode: "dispositivo",
        lojaId: input.dispositivo.loja_id,
        empresaId: input.dispositivo.empresa_id,
        dispositivoId: input.dispositivo.id,
      },
    };
  }
  if (!input.legacyEnabled || !input.legacyKey) return { ok: false, error: "DEVICE_NOT_ALLOWED" };
  return { ok: true, expectedKey: input.legacyKey, ctx: { mode: "legado", lojaId: header } };
}

function parsePayload(raw: string): Record<string, unknown> {
  const p = JSON.parse(raw);
  if (!p || typeof p !== "object" || Array.isArray(p)) throw new Error("PAYLOAD_INVALIDO");
  return p as Record<string, unknown>;
}

function str(v: unknown): string | null {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

/**
 * Garante que um evento da outbox (inclusive REPLAY offline de eventos antigos) só toca dados da loja
 * do dispositivo. Modo legado: no-op (comportamento atual do cliente 1).
 * Lança Error com código estável; o evento vai para `failed` e nada é escrito.
 */
export async function assertEventoNoEscopo(
  ev: { tipo: string; payload_json: string },
  ctx: SyncContext,
  lookups: ScopeLookups,
): Promise<void> {
  if (ctx.mode !== "dispositivo") return;
  const loja = ctx.lojaId;
  const p = parsePayload(ev.payload_json);

  const lojaPayload = str(p.loja_id);
  if (lojaPayload && lojaPayload !== loja) throw new Error("EVENTO_LOJA_FORA_DO_DISPOSITIVO");

 // Operador informado precisa ter vínculo ativo na loja do dispositivo (§10: venda de operador de
  // outra empresa/loja, ou desligado, não entra — inclusive em replay offline).
  const operador = str(p.operador_id);
  if (operador && (ev.tipo === "VENDA_REGISTRADA" || ev.tipo === "CAIXA_ABERTO" || ev.tipo === "MOVIMENTO_CAIXA")) {
    if (!(await lookups.operadorPodeLoja(operador, loja))) throw new Error("EVENTO_OPERADOR_SEM_VINCULO");
  }

  const caixaId = ev.tipo === "CAIXA_ABERTO" || ev.tipo === "CAIXA_FECHADO" ? str(p.id) : str(p.caixa_id);

  if (ev.tipo === "CAIXA_ABERTO") {
    if (!lojaPayload) throw new Error("EVENTO_LOJA_OBRIGATORIA");
    if (caixaId) {
      const existente = await lookups.caixaLoja(caixaId);
      if (existente !== null && existente !== loja) throw new Error("EVENTO_CAIXA_DE_OUTRA_LOJA");
    }
    return;
  }

  if (ev.tipo === "CAIXA_FECHADO" || ev.tipo === "MOVIMENTO_CAIXA" || ev.tipo === "VENDA_REGISTRADA") {
    if (!caixaId) throw new Error("EVENTO_CAIXA_OBRIGATORIO");
    const lojaCaixa = await lookups.caixaLoja(caixaId);
    // VENDA_REGISTRADA pode criar o caixa (ensureCaixaPdv) — só aceita se o caixa ainda não existe
    // E a loja do payload é a do dispositivo.
    if (lojaCaixa === null) {
      if (ev.tipo !== "VENDA_REGISTRADA" || lojaPayload !== loja) throw new Error("EVENTO_CAIXA_DESCONHECIDO");
    } else if (lojaCaixa !== loja) {
      throw new Error("EVENTO_CAIXA_DE_OUTRA_LOJA");
    }
    if (ev.tipo === "VENDA_REGISTRADA") {
      const itens = Array.isArray(p.itens) ? p.itens : [];
      const ids = [...new Set(itens.map((i) => str((i as Record<string, unknown>)?.produto_id)).filter((x): x is string => !!x))];
      if (ids.length > 0 && (await lookups.produtosForaDaLoja(ids, loja)) > 0) {
        throw new Error("EVENTO_PRODUTO_DE_OUTRA_LOJA");
      }
    }
    return;
  }
  throw new Error(`TIPO_DESCONHECIDO: ${ev.tipo}`);
}

const ALFABETO = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"; // sem 0/O/1/I/L

/** Forma canônica do código (igual à do banco): só [A-Z0-9] maiúsculo; hífens/espaços ignorados. */
export function normalizarCodigoAtivacao(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const t = raw.trim().toUpperCase();
  if (!/^[A-Z0-9\s-]+$/.test(t)) return null;
  const c = t.replace(/[^A-Z0-9]/g, "");
  if (c.length < 8 || c.length > 32) return null;
  return c;
}

export { ALFABETO as ALFABETO_CODIGO_ATIVACAO };
